  <div className="w-full bg-gray-200 rounded-full h-2.5 mb-8">
    <div 
      className="bg-[#FFB703] h-2.5 rounded-full transition-all duration-500" 
      style={{ width: `${(step / totalSteps) * 100}%` }}
    ></div>
  </div>
);

const Contact: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    injury_date: '',
    appointment_date: '',
    message: ''
  });
  const [step, setStep] = useState(1);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFormSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (step === 1) {
      if (!formData.name || !formData.phone || !formData.email) {
        setError('Please fill out all required fields.');
        return;
      }
      setStep(2);
    } else if (step === 2) {
      if (isSubmitted || isLoading) return;
      if (!formData.message) {
        setError('Please tell us a bit about your case.');
        return;
      }

      setIsLoading(true);

      // Simulate network delay for better UX
      await new Promise(resolve => setTimeout(resolve, 1000));

      try {
        addInquiry({
          name: formData.name,
          phone: formData.phone,
          email: formData.email,
          injuryDate: formData.injury_date,
          appointmentRequestDate: formData.appointment_date,
          message: formData.message,
        });
        setIsSubmitted(true);
      } catch (err) {
        setError('There was an error submitting your inquiry. Please try again later.');
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleBack = () => {
    setError('');
    setStep(s => s - 1);
  };

  // Get today's date for min attribute on date picker
  const today = new Date().toISOString().split('T')[0];

  const renderStepContent = () => {
    if (step === 1) {
      return (
        <>
          <h2 className="text-2xl font-bold text-[#0F1E4A] mb-2">Step 1: Your Contact Info</h2>
          <p className="text-gray-600 mb-6">Let's start with the basics.</p>
          <div className="space-y-6">
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-gray-700">Full Name *</label>
              <input type="text" name="name" id="name" required value={formData.name} onChange={handleChange} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703]" />
            </div>
            <div>
              <label htmlFor="phone" className="block text-sm font-medium text-gray-700">Phone Number *</label>
              <input type="tel" name="phone" id="phone" required value={formData.phone} onChange={handleChange} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703]" />
            </div>
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700">Email Address *</label>
              <input type="email" name="email" id="email" required value={formData.email} onChange={handleChange} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703]" />
            </div>
            <div className="flex justify-end">
              <button type="submit" className="w-full sm:w-auto flex justify-center py-3 px-8 border border-transparent rounded-md shadow-sm text-lg font-bold text-[#0F1E4A] bg-[#FFB703] hover:bg-yellow-400 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FFB703]">
                Next &rarr;
              </button>
            </div>
          </div>
        </>
      );
    }
    if (step === 2) {
      return (
        <>
          <h2 className="text-2xl font-bold text-[#0F1E4A] mb-2">Step 2: Case Details</h2>
          <p className="text-gray-600 mb-6">Help us understand your situation.</p>
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <label htmlFor="injury_date" className="block text-sm font-medium text-gray-700">Date of Injury (Optional)</label>
                    <input type="date" name="injury_date" id="injury_date" value={formData.injury_date} onChange={handleChange} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703]" />
                </div>
                <div>
                    <label htmlFor="appointment_date" className="block text-sm font-medium text-gray-700">Preferred Consultation Date</label>
                    <input 
                        type="date" 
                        name="appointment_date" 
                        id="appointment_date" 
                        min={today}
                        value={formData.appointment_date} 
                        onChange={handleChange} 
                        className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703]" 
                    />
                </div>
            </div>

            <div>
              <label htmlFor="message" className="block text-sm font-medium text-gray-700">Tell us about your case *</label>
              <textarea id="message" name="message" rows={5} required value={formData.message} onChange={handleChange} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703]"></textarea>
            </div>
            <div className="flex justify-between items-center">
              <button type="button" onClick={handleBack} className="px-6 py-3 text-sm font-medium text-gray-700 bg-gray-200 rounded-md hover:bg-gray-300 disabled:opacity-50" disabled={isLoading}>
                &larr; Back
