              <button type="submit" className="flex justify-center items-center py-3 px-8 border border-transparent rounded-md shadow-sm text-lg font-bold text-[#0F1E4A] bg-[#FFB703] hover:bg-yellow-400 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FFB703] disabled:opacity-70 disabled:cursor-not-allowed" disabled={isLoading}>
                {isLoading ? (
                  <>
                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-[#0F1E4A]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Submitting...
                  </>
                ) : (
                  'Submit Inquiry'
                )}
              </button>
            </div>
          </div>
        </>
      );
    }
    return null;
  }

  return (
    <div className="bg-white">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8 pt-20 pb-32">
        <AnimatedComponent>
          <div className="text-center mb-12">
            <h1 className="text-4xl md:text-5xl font-extrabold text-[#0F1E4A]">
              Contact Our Workers' Comp Attorneys for a Free Consultation
            </h1>
            <p className="mt-4 max-w-2xl mx-auto text-lg text-gray-600">
              Your road to recovery and financial security starts here. Reach out to our experienced California work injury lawyers today and let us fight for you.
            </p>
            <div className="mt-8">
              <a href="tel:818-791-0743" className="cta-shimmer inline-block bg-[#FFB703] text-[#0F1E4A] font-bold text-xl sm:text-2xl py-3 px-8 sm:py-4 sm:px-12 rounded-lg shadow-lg hover:bg-yellow-400 transform hover:scale-105">
                Call Us: (818) 791-0743
