            </div>
          </div>
        </AnimatedComponent>

        <AnimatedComponent>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-start">
            <div className="bg-gray-50 p-8 rounded-lg shadow-lg">
              {isSubmitted ? (
                <div className="text-center py-12 min-h-[400px] flex flex-col justify-center animate-fade-in">
