              <div className="flex-grow aspect-video min-h-[300px] rounded-lg overflow-hidden shadow-lg border border-gray-200">
                <iframe
                  src="https://maps.google.com/maps?q=3940%20Laurel%20Canyon%20Boulevard%2C%20%231493%2C%20Studio%20City%2C%20CA%2091604&t=&z=15&ie=UTF8&iwloc=&output=embed"
                  className="w-full h-full border-0"
