// Helper to update or create a meta tag
const updateMetaTag = (identifier: string, content: string, isProperty: boolean = true) => {
  const selector = isProperty ? `meta[property="${identifier}"]` : `meta[name="${identifier}"]`;
  let tag = document.querySelector(selector) as HTMLMetaElement | null;
  if (!tag) {
    tag = document.createElement('meta');
    if (isProperty) {
      tag.setAttribute('property', identifier);
    } else {
      tag.setAttribute('name', identifier);
    }
    document.head.appendChild(tag);
  }
  tag.setAttribute('content', content);
};

// Helper to manage robots meta tag
const updateRobotsTag = (content: string) => {
  let tag = document.querySelector('meta[name="robots"]') as HTMLMetaElement | null;
  if (!tag) {
    tag = document.createElement('meta');
    tag.setAttribute('name', 'robots');
    document.head.appendChild(tag);
  }
  tag.setAttribute('content', content);
};

// Helper to manage structured data script
const updateStructuredData = (data: object | null) => {
    const scriptId = 'app-structured-data';
    let script = document.getElementById(scriptId) as HTMLScriptElement | null;

    if (script && !data) {
        script.remove();
        return;
    }

    if (!script) {
        script = document.createElement('script');
        script.id = scriptId;
        script.type = 'application/ld+json';
        document.head.appendChild(script);
    }

    script.innerHTML = data ? JSON.stringify(data) : '';
};

