    updateMetaTag('twitter:url', `${domain}${pageMeta.path}`);
    updateMetaTag('og:type', pageMeta.ogType);
    updateRobotsTag(pageMeta.noIndex ? 'noindex, nofollow' : 'index, follow');

    if (currentPage !== 'blogPost') {
        updateStructuredData(pageMeta.structuredData);
    } else {
        updateStructuredData(null); 
    }

    let canonicalTag = document.querySelector('link[rel="canonical"]');
    if (canonicalTag) {
      canonicalTag.setAttribute('href', `${domain}${pageMeta.path}`);
    }

  }, [currentPage, currentPostSlug, selectedFormType]);


  const navigate = useCallback((page: Page) => {
    setCurrentPage(page);
    if (page !== 'blogPost') {
      setCurrentPostSlug(null);
    }
    window.scrollTo(0, 0);
  }, []);

  const navigateToPost = useCallback((slug: string) => {
    setCurrentPage('blogPost');
    setCurrentPostSlug(slug);
    window.scrollTo(0, 0);
  }, []);

  const navigateToForm = useCallback((formType: FormType) => {
    setSelectedFormType(formType);
    setCurrentPage('form-viewer');
    window.scrollTo(0, 0);
  }, []);

  const handleAcceptCookies = () => {
    localStorage.setItem('cookie_consent', 'accepted');
    setShowConsentBanner(false);
  };

  const handleDeclineCookies = () => {
    localStorage.setItem('cookie_consent', 'declined');
    setShowConsentBanner(false);
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Homepage navigate={navigate} navigateToPost={navigateToPost} />;
      case 'services':
        return <Services navigate={navigate} navigateToForm={navigateToForm} />;
      case 'form-viewer':
         return <FormPage formType={selectedFormType} navigate={navigate} />;
      case 'practice-areas':
        return <PracticeAreas navigate={navigate} />;
      case 'our-method':
        return <OurMethod navigate={navigate} />;
      case 'case-results':
        return <CaseResults navigate={navigate} />;
      case 'tools':
        return <Tools navigate={navigate} />;
      case 'team':
        return <Team />;
      case 'faqs':
        return <FAQs />;
      case 'contact':
        return <Contact />;
      case 'blog':
        return <Blog navigateToPost={navigateToPost} />;
      case 'news':
        return <News />;
      case 'weekly-analysis':
        return <WeeklyAnalysis />;
      case 'blogPost':
        return <BlogPostPage slug={currentPostSlug} navigate={navigate} navigateToPost={navigateToPost} />;
      case 'admin':
        return <Admin />;
      case 'terms-of-use':
        return <TermsOfUse />;
      case 'sitemap':
        return <Sitemap />;
      default:
        return <Homepage navigate={navigate} navigateToPost={navigateToPost} />;
    }
  };

  return (
    <div className="bg-gray-50 min-h-screen flex flex-col">
      <Header 
        navigate={navigate} 
        currentPage={currentPage}
        isMobileMenuOpen={isMobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen} 
      />
      <div className={`flex-grow flex flex-col transition-filter duration-300 ${isMobileMenuOpen ? 'blur-sm pointer-events-none' : ''}`}>
        <main className="flex-grow">
          <Suspense fallback={<LoadingSpinner />}>
            {renderPage()}
          </Suspense>
        </main>
        <Footer navigate={navigate} setShowCookiePolicy={setShowCookiePolicy}/>
      </div>
      <GeminiChatbot navigate={navigate} currentPage={currentPage} />
      {showCookiePolicy && 
        <Suspense fallback={<div />}>
          <CookiePolicy onClose={() => setShowCookiePolicy(false)} />
        </Suspense>
      }
      {showConsentBanner && (
        <Suspense fallback={<div />}>
            <CookieConsentBanner 
                onAccept={handleAcceptCookies}
                onDecline={handleDeclineCookies}
                onShowPolicy={() => setShowCookiePolicy(true)}
            />
        </Suspense>
      )}
    </div>
  );
};

