let activeChat: Chat | null = null;

const initializeChat = (model: string = PRIMARY_MODEL) => {
    activeChat = ai.chats.create({
      model: model,
      config: {
        systemInstruction: getSystemInstruction(),
        tools: [{ functionDeclarations: [navigateToPageDeclaration, scheduleAppointmentDeclaration] }, { googleSearch: {} }],
      },
    });
    return activeChat;
};

export async function* askGeminiStream(message: string, currentPageName: string): AsyncGenerator<ChatMessage> {
  try {
    if (!activeChat) initializeChat();
    const chat = activeChat!;

    const context = `[User Location: ${currentPageName}]\n\n${message}`;
    const stream = await chat.sendMessageStream({ message: context });

    let accumulatedText = '';
    for await (const chunk of stream) {
      const chunkText = chunk.text; // Guideline: access .text property
      if (chunkText) {
        accumulatedText += chunkText;
        yield { sender: 'gemini', text: accumulatedText };
      }

      if (chunk.functionCalls && chunk.functionCalls.length > 0) {
          for (const fc of chunk.functionCalls) {
              if (fc.name === 'navigateToPage') {
                  yield {
                      sender: 'gemini',
                      text: accumulatedText || `Let me take you to the ${fc.args.pageName}.`,
                      functionCall: { name: 'navigateToPage', args: fc.args }
                  };
              } else if (fc.name === 'scheduleAppointment') {
                  const appt = addAppointment(fc.args as any);
                  const confirmText = `\n\n✅ **Consultation Confirmed**: I've scheduled your appointment for ${appt.date} at ${appt.time}. Our team will contact you at your provided info.`;
                  yield { sender: 'gemini', text: accumulatedText + confirmText };
                  // Sync history
                  await chat.sendMessage({
                      functionResponses: [{ name: 'scheduleAppointment', response: { status: 'success', id: appt.id } }]
                  });
              }
          }
      }
    }
  } catch (error) {
    console.error("Chat Error:", error);
    yield { sender: 'gemini', text: "I apologize, I'm having trouble connecting. Please call us directly at (818) 791-0743 for immediate help." };
  }
}

export const generateImageForPost = async (title: string): Promise<string | null> => {
    try {
        const response = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: `Professional, high-end architectural or abstract legal imagery for a blog titled: "${title}". Soft lighting, high contrast, no text.` }] },
            config: { imageConfig: { aspectRatio: "16:9" } }
        }));

        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                return `data:image/png;base64,${part.inlineData.data}`;
            }
        }
        return null;
    } catch (e) {
        return null;
    }
};

