const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const [currentPostSlug, setCurrentPostSlug] = useState<string | null>(null);
  const [selectedFormType, setSelectedFormType] = useState<FormType | null>(null);
  const [showCookiePolicy, setShowCookiePolicy] = useState(false);
  const [showConsentBanner, setShowConsentBanner] = useState(() => !localStorage.getItem('cookie_consent'));
  const [isMobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    checkAndGenerateWeeklyPost();
  }, []);

  // Centralized SEO Engine
  useEffect(() => {
    const domain = window.location.origin;
    const post = currentPostSlug ? getBlogPostBySlug(currentPostSlug) : null;

    let title = `${metadata.name} | California Workers' Comp Attorneys`;
    let desc = "Dedicated legal representation for California workers. Free consultation.";

    if (post) {
      title = `${post.title} | ${metadata.name}`;
      desc = post.metaDescription || post.excerpt;
    } else if (currentPage !== 'home') {
      const pageName = currentPage.split('-').map(s => s.charAt(0).toUpperCase() + s.slice(1)).join(' ');
      title = `${pageName} | ${metadata.name}`;
    }

    document.title = title;

    // Update Meta Tags
    const update = (name: string, content: string, property = false) => {
      const selector = property ? `meta[property="${name}"]` : `meta[name="${name}"]`;
      let el = document.querySelector(selector);
      if (!el) {
        el = document.createElement('meta');
        if (property) el.setAttribute('property', name);
        else el.setAttribute('name', name);
        document.head.appendChild(el);
      }
      el.setAttribute('content', content);
    };

    update('description', desc);
    update('og:title', title, true);
    update('og:description', desc, true);
    update('og:url', window.location.href, true);
    update('og:type', post ? 'article' : 'website', true);

    let canonical = document.querySelector('link[rel="canonical"]');
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    canonical.setAttribute('href', window.location.href);

  }, [currentPage, currentPostSlug]);

  const navigate = useCallback((page: Page) => {
    setCurrentPage(page);
    setCurrentPostSlug(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setMobileMenuOpen(false);
  }, []);

  const navigateToPost = useCallback((slug: string) => {
    setCurrentPostSlug(slug);
    setCurrentPage('blogPost');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  const navigateToForm = useCallback((formType: FormType) => {
    setSelectedFormType(formType);
    setCurrentPage('form-viewer');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  const activePage = useMemo(() => {
    switch (currentPage) {
      case 'home': return <Homepage navigate={navigate} navigateToPost={navigateToPost} />;
      case 'practice-areas': return <PracticeAreas navigate={navigate} />;
      case 'case-results': return <CaseResults navigate={navigate} />;
      case 'tools': return <Tools navigate={navigate} />;
      case 'team': return <Team />;
      case 'faqs': return <FAQs />;
      case 'contact': return <Contact />;
      case 'blog': return <Blog navigateToPost={navigateToPost} />;
      case 'blogPost': return <BlogPostPage slug={currentPostSlug} navigate={navigate} navigateToPost={navigateToPost} />;
      case 'services': return <Services navigate={navigate} navigateToForm={navigateToForm} />;
      case 'form-viewer': return <FormPage formType={selectedFormType} navigate={navigate} />;
      case 'news': return <News />;
      case 'weekly-analysis': return <WeeklyAnalysis />;
      case 'our-method': return <OurMethod navigate={navigate} />;
      case 'sitemap': return <Sitemap />;
      default: return <Homepage navigate={navigate} navigateToPost={navigateToPost} />;
    }
  }, [currentPage, currentPostSlug, selectedFormType, navigate, navigateToPost, navigateToForm]);

  return (
    <div className="bg-gray-50 min-h-screen flex flex-col selection:bg-[#FFB703]/30">
      <Header 
        navigate={navigate} 
        currentPage={currentPage}
        isMobileMenuOpen={isMobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen} 
      />

      <main className={`flex-grow transition-all duration-300 ${isMobileMenuOpen ? 'blur-sm grayscale pointer-events-none' : ''}`}>
        <Suspense fallback={<LoadingSpinner />}>
          {activePage}
        </Suspense>
      </main>

      <Footer navigate={navigate} setShowCookiePolicy={setShowCookiePolicy} />

      <GeminiChatbot navigate={navigate} currentPage={currentPage} />

      {showCookiePolicy && <CookiePolicy onClose={() => setShowCookiePolicy(false)} />}

      {showConsentBanner && (
        <CookieConsentBanner 
          onAccept={() => { localStorage.setItem('cookie_consent', 'true'); setShowConsentBanner(false); }}
          onDecline={() => { localStorage.setItem('cookie_consent', 'false'); setShowConsentBanner(false); }}
          onShowPolicy={() => setShowCookiePolicy(true)}
        />
      )}
    </div>
  );
};

