import { GoogleGenAI, FunctionDeclaration, Type, Chat, GenerateContentResponse, GroundingChunk, Modality } from "@google/genai";
import type { ChatMessage, Page, Citation, NewsItem, BlogPost } from '../types';
import { 
    getWeeklyAnalysis, setWeeklyAnalysis, 
    getDailyNews, setDailyNews, 
    getAllBlogPosts, addBlogPost,
    getPracticeAreaIntroCache, setPracticeAreaIntroCache
} from './contentService';
import { addAppointment } from './appointmentService';

// Ensure API Key is strictly pulled from process.env as per requirements
const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set. Application cannot initialize GenAI features.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Models specified in developer guidelines
const PRIMARY_MODEL = 'gemini-3-pro-preview';
const FALLBACK_MODEL = 'gemini-3-flash-preview';

/**
 * Robust API call wrapper with exponential backoff
 */
const callWithRetry = async <T>(
    apiCall: () => Promise<T>,
    retries: number = 3,
    delay: number = 2000
): Promise<T> => {
    try {
        return await apiCall();
    } catch (error: any) {
        const errStr = error.toString();
        const isRetryable = error.status === 429 || errStr.includes('429') || errStr.includes('RESOURCE_EXHAUSTED') || errStr.includes('quota');

        if (isRetryable && retries > 0) {
            console.warn(`Gemini API rate limit. Retrying in ${delay}ms...`);
            await new Promise(r => setTimeout(r, delay));
            return callWithRetry(apiCall, retries - 1, delay * 2);
        }
        throw error;
    }
};

const isAuthError = (error: any) => {
    const s = error.toString();
    return error.status === 403 || s.includes('PERMISSION_DENIED') || error.status === 401;
};

/**
 * Unified generation helper with model fallback
 */
const generateWithFallback = async (params: any): Promise<GenerateContentResponse> => {
    try {
        return await callWithRetry(() => ai.models.generateContent({
            model: PRIMARY_MODEL,
            ...params
        }));
    } catch (error: any) {
        if (isAuthError(error) || error.status === 429) {
            console.warn(`Switching to fallback model: ${FALLBACK_MODEL}`);
            return await callWithRetry(() => ai.models.generateContent({
                model: FALLBACK_MODEL,
                ...params
            }));
        }
        throw error;
    }
};

