1. **Lead Conversion**: If a user mentions a work injury, explain their rights simply and ask if they'd like to schedule a free consultation.
2. **Scheduling**: Use the 'scheduleAppointment' tool when a user provides a date/time.
3. **Navigation**: Use 'navigateToPage' to show them case results or our calculator.
4. **Safety**: NEVER provide specific legal advice. Always state: "I can provide general information, but for legal advice specific to your case, you should speak with our attorneys directly."
5. **No Key Requests**: Never ask the user for an API key.`;
};

const navigateToPageDeclaration: FunctionDeclaration = {
  name: 'navigateToPage',
  description: "Navigates the user to a specific section of the website.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      page: {
        type: Type.STRING,
        enum: ['home', 'practice-areas', 'case-results', 'tools', 'team', 'faqs', 'contact', 'blog', 'news', 'weekly-analysis'],
      },
      pageName: { type: Type.STRING }
    },
    required: ['page', 'pageName'],
  },
};

const scheduleAppointmentDeclaration: FunctionDeclaration = {
  name: 'scheduleAppointment',
  description: "Records a consultation request in our calendar.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      date: { type: Type.STRING, description: "YYYY-MM-DD" },
      time: { type: Type.STRING, description: "HH:MM" },
      reason: { type: Type.STRING }
    },
    required: ['name', 'date', 'time', 'reason']
  }
};

let activeChat: Chat | null = null;

const initializeChat = (model: string = PRIMARY_MODEL) => {
    activeChat = ai.chats.create({
      model: model,
      config: {
        systemInstruction: getSystemInstruction(),
        // Rule: googleSearch must not be used with other tools. Keeping function declarations for core app functionality.
        tools: [{ functionDeclarations: [navigateToPageDeclaration, scheduleAppointmentDeclaration] }],
      },
    });
    return activeChat;
};

export async function* askGeminiStream(message: string, currentPageName: string): AsyncGenerator<ChatMessage> {
  try {
    if (!activeChat) initializeChat();
    const chat = activeChat!;

    const context = `[User Location: ${currentPageName}]\n\n${message}`;
    const stream = await chat.sendMessageStream({ message: context });

    let accumulatedText = '';
    for await (const chunk of stream) {
      const chunkText = chunk.text; // Guideline: access .text property
      if (chunkText) {
        accumulatedText += chunkText;
        yield { sender: 'gemini', text: accumulatedText };
      }

      if (chunk.functionCalls && chunk.functionCalls.length > 0) {
          for (const fc of chunk.functionCalls) {
              if (fc.name === 'navigateToPage') {
                  yield {
                      sender: 'gemini',
                      text: accumulatedText || `Let me take you to the ${fc.args.pageName}.`,
                      functionCall: { name: 'navigateToPage', args: fc.args }
                  };
              } else if (fc.name === 'scheduleAppointment') {
                  const appt = addAppointment(fc.args as any);
                  const confirmText = `\n\n✅ **Consultation Confirmed**: I've scheduled your appointment for ${appt.date} at ${appt.time}. Our team will contact you at your provided info.`;
                  yield { sender: 'gemini', text: accumulatedText + confirmText };
                  // Sync history
                  await chat.sendMessage({
                      functionResponses: [{ name: 'scheduleAppointment', response: { status: 'success', id: appt.id } }]
                  });
              }
          }
      }
    }
  } catch (error) {
    console.error("Chat Error:", error);
    yield { sender: 'gemini', text: "I apologize, I'm having trouble connecting. Please call us directly at (818) 791-0743 for immediate help." };
  }
}

/**
