export const generateImageForPost = async (title: string): Promise<string | null> => {
    try {
        // Fix: Explicitly type the response to ensure candidates property is accessible
        const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: `Professional, high-end architectural or abstract legal imagery for a blog titled: "${title}". Soft lighting, high contrast, no text.` }] },
            config: { imageConfig: { aspectRatio: "16:9" } }
        }));

        const candidates = response.candidates;
        if (candidates && candidates.length > 0) {
            for (const part of candidates[0].content.parts) {
                if (part.inlineData) {
                    return `data:image/png;base64,${part.inlineData.data}`;
                }
            }
        }
        return null;
    } catch (e) {
        return null;
    }
};

