    const posts = getAllBlogPosts();
    if (posts.length === 0) return;

    const latestDate = new Date(posts[0].publishedDate);
    const diff = (new Date().getTime() - latestDate.getTime()) / (1000 * 3600 * 24);

    if (diff > 7) {
        console.log("Auto-generating weekly content...");
        try {
            const res = await generateWithFallback({
                contents: "Generate a unique, high-quality blog post about CA workers comp law. JSON format.",
                config: {
                    responseMimeType: "application/json",
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            title: { type: Type.STRING },
                            slug: { type: Type.STRING },
                            excerpt: { type: Type.STRING },
                            content: { type: Type.STRING },
                            category: { type: Type.STRING },
                            metaDescription: { type: Type.STRING },
