            console.error("Auto-gen failed:", e);
        }
    }
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import type { ChatMessage, Page } from '../types';
import { askGeminiStream } from '../services/geminiService';
import { useTranslation } from '../hooks/useTranslation';

interface GeminiChatbotProps {
  navigate: (page: Page) => void;
  currentPage: Page;
}

const GeminiChatbot: React.FC<GeminiChatbotProps> = ({ navigate, currentPage }) => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const welcomeMsg = useMemo(() => t('ai_welcome' as any) || "Hello! I'm Justice. How can I help with your work injury today?", [t]);

  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ sender: 'gemini', text: welcomeMsg }]);
    }
  }, [welcomeMsg, messages.length]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    if (isOpen) inputRef.current?.focus();
  }, [messages, isOpen]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim() || isLoading) return;

    const userText = userInput;
    setUserInput('');
    setIsLoading(true);

    setMessages(prev => [...prev, { sender: 'user', text: userText }, { sender: 'gemini', text: '' }]);

    try {
        const stream = askGeminiStream(userText, currentPage);
        for await (const chunk of stream) {
            setMessages(prev => {
                const newMsgs = [...prev];
                newMsgs[newMsgs.length - 1] = chunk;
                return newMsgs;
            });
            if (chunk.functionCall) {
                if (chunk.functionCall.name === 'navigateToPage') {
                    setTimeout(() => {
                        navigate(chunk.functionCall!.args.page);
                        setIsOpen(false);
                    }, 1500);
                }
            }
        }
    } catch (err) {
        setMessages(prev => [...prev.slice(0, -1), { sender: 'gemini', text: "Connection error. Please call us at (818) 791-0743." }]);
    } finally {
        setIsLoading(false);
    }
  };

  return (
    <>
      <div className={`fixed bottom-6 right-6 z-50 transition-all transform ${isOpen ? 'scale-0' : 'scale-100'}`}>
        <button
          onClick={() => setIsOpen(true)}
          className="bg-[#FFB703] text-[#0F1E4A] p-4 rounded-full shadow-2xl hover:scale-110 active:scale-95 transition-all animate-pulse-slow"
          aria-label={t('openChat')}
        >
          <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z" /></svg>
        </button>
      </div>

      <div className={`fixed bottom-0 right-0 sm:bottom-6 sm:right-6 z-50 w-full h-full sm:w-[400px] sm:h-[600px] bg-white shadow-2xl rounded-t-2xl sm:rounded-2xl flex flex-col transition-all duration-300 transform ${isOpen ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0 pointer-events-none'}`}>
        <header className="bg-[#0F1E4A] text-white p-5 flex justify-between items-center rounded-t-2xl">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse" />
            <div>
              <h3 className="font-bold">{t('aiAssistant')}</h3>
              <p className="text-xs text-blue-200">Justice • Jimenez Law APC</p>
            </div>
          </div>
          <button onClick={() => setIsOpen(false)} className="hover:rotate-90 transition-transform p-1">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed shadow-sm ${msg.sender === 'user' ? 'bg-[#FFB703] text-[#0F1E4A] font-medium rounded-br-none' : 'bg-white text-gray-800 rounded-bl-none border border-gray-100'}`}>
                {msg.text || (isLoading && idx === messages.length - 1 ? <div className="flex gap-1 py-1"><div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" /><div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.2s]" /><div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.4s]" /></div> : null)}
                {msg.text}
                {msg.citations && (
                  <div className="mt-3 pt-3 border-t border-gray-100 space-y-1">
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">{t('sources')}</p>
                    {msg.citations.map((c, i) => <a key={i} href={c.uri} target="_blank" className="block text-xs text-blue-600 hover:underline truncate">{c.title}</a>)}
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        <form onSubmit={handleSendMessage} className="p-4 border-t bg-white sm:rounded-b-2xl">
          <div className="relative">
            <input
              ref={inputRef}
              type="text"
              value={userInput}
              onChange={(e) => setUserInput(e.target.value)}
              placeholder={t('askAQuestion')}
              className="w-full pl-4 pr-12 py-3 bg-gray-100 border-none rounded-xl focus:ring-2 focus:ring-[#FFB703] transition-all"
              disabled={isLoading}
            />
            <button type="submit" disabled={!userInput.trim() || isLoading} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-[#0F1E4A] hover:text-blue-700 disabled:opacity-30">
                <svg className="w-6 h-6 rotate-90" fill="currentColor" viewBox="0 0 20 20"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </form>
      </div>
    </>
  );
};

export default GeminiChatbot;

