  const diff = (Date.now() - new Date(posts[0].publishedDate).getTime()) / (1000 * 3600 * 24);
  if (diff > 7) {
    try {
      const res = await generateContent("Generate a high-quality CA workers comp blog post. JSON format.", MODELS.PRIMARY, {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: { title: { type: Type.STRING }, slug: { type: Type.STRING }, excerpt: { type: Type.STRING }, content: { type: Type.STRING }, category: { type: Type.STRING } }
        }
      });
      const data = JSON.parse(res.text || '{}');
      const img = await generateImageForPost(data.title);
      addBlogPost({ ...data, imageUrl: img || 'https://picsum.photos/800/600', publishedDate: new Date().toISOString().split('T')[0], citations: [], metaDescription: data.excerpt, metaKeywords: data.category });
    } catch (e) { console.error(e); }
  }
};

import type { BlogPost, Testimonial, TeamMember, FAQItem, WeeklyAnalysisContent, DailyNewsContent, NewsItem } from '../types';
