const STORAGE_KEYS = {
    BLOG_POSTS: 'jla_custom_blog_posts',
    TEAM: 'jla_custom_team',
    WEEKLY_ANALYSIS: 'jla_cache_weekly_analysis',
    DAILY_NEWS: 'jla_cache_daily_news',
    PRACTICE_INTRO: 'jla_cache_practice_intro'
};

const getDateDaysAgo = (days: number) => {
    const date = new Date();
    date.setDate(date.getDate() - days);
    return date.toISOString().split('T')[0];
};

let staticBlogPosts: BlogPost[] = [
