  }
];

// Helper to get all combined posts
export const getAllBlogPosts = (): BlogPost[] => {
  const stored = localStorage.getItem(STORAGE_KEYS.BLOG_POSTS);
  const custom = stored ? JSON.parse(stored) : [];
  return [...staticBlogPosts, ...custom].sort((a, b) => new Date(b.publishedDate).getTime() - new Date(a.publishedDate).getTime());
};

export const getLatestBlogPosts = () => getAllBlogPosts().slice(0, 3);
export const getBlogPostBySlug = (slug: string) => getAllBlogPosts().find(p => p.slug === slug);
export const getBlogPostById = (id: number) => getAllBlogPosts().find(p => p.id === id);

export const addBlogPost = (postData: Omit<BlogPost, 'id'>) => {
  const posts = getAllBlogPosts();
  const nextId = posts.length ? Math.max(...posts.map(p => p.id)) + 1 : 1;
  const newPost = { ...postData, id: nextId };

  const stored = localStorage.getItem(STORAGE_KEYS.BLOG_POSTS);
  const custom = stored ? JSON.parse(stored) : [];
  localStorage.setItem(STORAGE_KEYS.BLOG_POSTS, JSON.stringify([...custom, newPost]));

  sendAdminNotification("New Blog Post", `Title: ${newPost.title}`);
  return newPost;
};

// Caching utilities
const getCache = <T>(key: string): T | null => {
  const data = localStorage.getItem(key);
  if (!data) return null;
  const parsed = JSON.parse(data);
  return Date.now() < parsed.expires ? parsed : null;
};

const setCache = (key: string, content: any, ttl: number) => {
  localStorage.setItem(key, JSON.stringify({ ...content, expires: Date.now() + ttl }));
};

