const LoadingSpinner: React.FC = () => (
  <div className="flex justify-center items-center py-40">
    <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-[#0F1E4A]"></div>
  </div>
);

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const [currentPostSlug, setCurrentPostSlug] = useState<string | null>(null);
  const [selectedFormType, setSelectedFormType] = useState<FormType | null>(null);
  const [showCookiePolicy, setShowCookiePolicy] = useState(false);
  const [showConsentBanner, setShowConsentBanner] = useState(() => !localStorage.getItem('cookie_consent'));
  const [isMobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Initialize weekly automation
  useEffect(() => {
    checkAndGenerateWeeklyPost();
  }, []);

  // Use custom hook for SEO/Meta
  useMeta(currentPage, currentPostSlug);

  const navigate = useCallback((page: Page) => {
    setCurrentPage(page);
    setCurrentPostSlug(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setMobileMenuOpen(false);
  }, []);

  const navigateToPost = useCallback((slug: string) => {
    setCurrentPostSlug(slug);
    setCurrentPage('blogPost');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  const navigateToForm = useCallback((formType: FormType) => {
    setSelectedFormType(formType);
    setCurrentPage('form-viewer');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  // Consolidate ActivePageContent to use standard component references and fixed scope
  const ActivePageContent = useMemo(() => {
    const pages: Record<Page, React.ReactNode> = {
      'home': <Homepage navigate={navigate} navigateToPost={navigateToPost} />,
      'practice-areas': <PracticeAreas navigate={navigate} />,
      'case-results': <CaseResults navigate={navigate} />,
      'tools': <Tools navigate={navigate} />,
      'team': <Team />,
      'faqs': <FAQs />,
      'contact': <Contact />,
      'blog': <Blog navigateToPost={navigateToPost} />,
      'blogPost': <BlogPostPage slug={currentPostSlug} navigate={navigate} navigateToPost={navigateToPost} />,
      'services': <Services navigate={navigate} navigateToForm={navigateToForm} />,
      'form-viewer': <FormPage formType={selectedFormType} navigate={navigate} />,
      'news': <News />,
      'weekly-analysis': <WeeklyAnalysis />,
      'our-method': <OurMethod navigate={navigate} />,
      'sitemap': <Sitemap />,
      'admin': <Admin />,
      'terms-of-use': <TermsOfUse />
    };

    return pages[currentPage] || pages['home'];
  }, [currentPage, currentPostSlug, selectedFormType, navigate, navigateToPost, navigateToForm]);

  return (
    <div className="bg-gray-50 min-h-screen flex flex-col selection:bg-[#FFB703]/30">
      <Header 
        navigate={navigate} 
        currentPage={currentPage}
        isMobileMenuOpen={isMobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen} 
      />

      <main className={`flex-grow transition-all duration-300 ${isMobileMenuOpen ? 'blur-sm grayscale pointer-events-none' : ''}`}>
        <Suspense fallback={<LoadingSpinner />}>
          {ActivePageContent}
        </Suspense>
      </main>

      <Footer navigate={navigate} setShowCookiePolicy={setShowCookiePolicy} />

      <GeminiChatbot navigate={navigate} currentPage={currentPage} />

      {showCookiePolicy && <CookiePolicy onClose={() => setShowCookiePolicy(false)} />}

      {showConsentBanner && (
        <CookieConsentBanner 
          onAccept={() => { localStorage.setItem('cookie_consent', 'true'); setShowConsentBanner(false); }}
          onDecline={() => { localStorage.setItem('cookie_consent', 'false'); setShowConsentBanner(false); }}
          onShowPolicy={() => setShowCookiePolicy(true)}
        />
      )}
    </div>
  );
};

