  try {
    const res = await generateContent(
      "List 3 major CA Workers' Comp news stories today. Return JSON array of {title, summary, url}.",
      MODELS.PRIMARY,
      {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            newsItems: {
              type: Type.ARRAY,
