                        <p className="mt-4 text-gray-600">Answer a few questions for a preliminary assessment of your workers' compensation potential.</p>
                    </div>
                </AnimatedComponent>

                {!isFinished ? (
                    <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
                        <div className="mb-8">
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-xs font-bold text-gray-400 uppercase">Question {currentStep + 1} of {questions.length}</span>
                                <span className="text-xs font-bold text-[#FFB703]">{Math.round(progress)}% Complete</span>
                            </div>
                            <div className="w-full bg-gray-100 h-2 rounded-full">
                                <div className="bg-[#FFB703] h-full rounded-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
