                                    {option.label}
                                    <svg className="w-5 h-5 text-gray-300 group-hover:text-[#FFB703] transform group-hover:translate-x-1 transition-all" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                                </button>
                            ))}
                        </div>
                    </div>
                ) : !isSubmitted ? (
                    <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100 animate-fade-in text-center">
                        <div className="inline-block p-4 rounded-full bg-green-50 mb-6">
                            <svg className="w-12 h-12 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        </div>
                        <h2 className="text-2xl font-bold text-[#0F1E4A] mb-4">Assessment Complete</h2>
                        <p className="text-gray-600 mb-8">Based on your answers, your case has strong potential. To receive a detailed professional evaluation from our attorneys, please provide your contact info below.</p>

                        <form onSubmit={handleLeadSubmit} className="space-y-4 text-left">
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">Full Name</label>
                                <input 
                                    type="text" required 
