export const addTeamMember = (member: Omit<TeamMember, 'id'>) => {
    const members = getTeamMembers();
    const newMember = { ...member, id: Math.random().toString(36).substring(2, 9) };
    localStorage.setItem(STORAGE_KEYS.TEAM, JSON.stringify([...members, newMember]));
    return newMember;
};

export const updateTeamMember = (member: TeamMember) => {
    const members = getTeamMembers();
    const updated = members.map((m: any) => m.id === member.id ? member : m);
    localStorage.setItem(STORAGE_KEYS.TEAM, JSON.stringify(updated));
};

export const deleteTeamMember = (id: string) => {
    const members = getTeamMembers();
    const updated = members.filter((m: any) => m.id !== id);
    localStorage.setItem(STORAGE_KEYS.TEAM, JSON.stringify(updated));
};

