// In-memory storage to simulate a backend. Data will reset on page refresh.
let inquiries: Inquiry[] = [];

export const getInquiries = (): Inquiry[] => {
  return inquiries;
};

export const addInquiry = (inquiryData: Omit<Inquiry, 'id' | 'submittedAt'>): Inquiry => {
  const newInquiry: Inquiry = {
    ...inquiryData,
    id: new Date().toISOString() + Math.random().toString(36).substring(2, 9),
    submittedAt: new Date().toISOString(),
  };
  inquiries = [newInquiry, ...inquiries]; // Add new inquiry to the top

  const dateReq = newInquiry.appointmentRequestDate ? `\nRequested Consultation Date: ${newInquiry.appointmentRequestDate}` : '';
  const heardFrom = newInquiry.howDidYouHear ? `\nHow they heard: ${newInquiry.howDidYouHear}` : '';

  // Notify Admin
  sendAdminNotification(
    "New Website Inquiry Received",
    `A new inquiry has been submitted via the contact form.\n\nName: ${newInquiry.name}\nEmail: ${newInquiry.email}\nPhone: ${newInquiry.phone}${dateReq}${heardFrom}\nMessage: ${newInquiry.message}`
  );

  // Send confirmation to User
  if (newInquiry.email) {
    sendUserConfirmation(newInquiry.email, newInquiry.name);
  }

  return newInquiry;
};

export const deleteInquiry = (inquiryId: string): void => {
    inquiries = inquiries.filter(inq => inq.id !== inquiryId);
}

