};

const callWithRetry = async <T>(apiCall: () => Promise<T>, retries = 3, delay = 2000): Promise<T> => {
  try {
    return await apiCall();
  } catch (error: any) {
    const isRetryable = error.status === 429 || error.toString().includes('quota');
    if (isRetryable && retries > 0) {
      await new Promise(r => setTimeout(r, delay));
      return callWithRetry(apiCall, retries - 1, delay * 2);
    }
    throw error;
  }
};

const generateContent = async (contents: any, model = MODELS.PRIMARY, config: any = {}): Promise<GenerateContentResponse> => {
  try {
    return await callWithRetry(() => ai.models.generateContent({ model, contents, config }));
  } catch (error: any) {
    if (model !== MODELS.FLASH) {
      console.warn("Falling back to Flash model...");
      return await callWithRetry(() => ai.models.generateContent({ model: MODELS.FLASH, contents, config }));
    }
    throw error;
  }
};

const getSystemInstruction = () => `**Persona: Justice, AI Assistant for Jimenez Law APC**
Firm Phone: (818) 791-0743. Focus on empathy and lead conversion.
Directives:
1. Lead Conversion: Offer free consultations for work injuries.
2. Scheduling: Use 'scheduleAppointment' tool for dates/times.
3. Navigation: Use 'navigateToPage' for site sections.
4. Safety: Never provide specific legal advice. Always disclaimer.`;

const TOOLS = [
  {
    name: 'navigateToPage',
    description: "Navigates the user to a specific section.",
    parameters: {
      type: Type.OBJECT,
      properties: {
        page: { type: Type.STRING, enum: ['home', 'practice-areas', 'case-results', 'tools', 'team', 'faqs', 'contact', 'blog', 'news', 'weekly-analysis'] },
        pageName: { type: Type.STRING }
      },
      required: ['page', 'pageName'],
    },
  },
  {
    name: 'scheduleAppointment',
    description: "Schedules a consultation.",
    parameters: {
      type: Type.OBJECT,
      properties: {
        name: { type: Type.STRING },
        date: { type: Type.STRING, description: "YYYY-MM-DD" },
        time: { type: Type.STRING, description: "HH:MM" },
        reason: { type: Type.STRING }
      },
      required: ['name', 'date', 'time', 'reason']
    }
  }
];

let activeChat: Chat | null = null;

export async function* askGeminiStream(message: string, currentPage: string): AsyncGenerator<ChatMessage> {
  if (!activeChat) {
    activeChat = ai.chats.create({
      model: MODELS.PRIMARY,
      config: {
        systemInstruction: getSystemInstruction(),
        tools: [{ functionDeclarations: TOOLS as any }],
      },
    });
  }

  try {
    const stream = await activeChat.sendMessageStream({ message: `[Location: ${currentPage}]\n\n${message}` });
    let fullText = '';

    for await (const chunk of stream) {
      if (chunk.text) {
        fullText += chunk.text;
        yield { sender: 'gemini', text: fullText };
      }

      if (chunk.functionCalls) {
        for (const fc of chunk.functionCalls) {
          if (fc.name === 'navigateToPage') {
            yield { sender: 'gemini', text: fullText, functionCall: { name: 'navigateToPage', args: fc.args } };
          } else if (fc.name === 'scheduleAppointment') {
            const appt = addAppointment(fc.args as any);
            const confirm = `\n\n✅ **Scheduled**: Consultation for ${appt.date} at ${appt.time}.`;
            fullText += confirm;
            yield { sender: 'gemini', text: fullText };
            await activeChat.sendMessage({ functionResponses: [{ name: 'scheduleAppointment', response: { status: 'success' }, id: fc.id }] });
          }
        }
      }
    }
  } catch (error) {
    yield { sender: 'gemini', text: "I'm having trouble connecting. Please call (818) 791-0743." };
  }
}

export const generateImageForPost = async (title: string): Promise<string | null> => {
  try {
    const res = await generateContent(
      `Professional architectural/abstract legal imagery for: "${title}". Soft lighting, no text.`,
      MODELS.IMAGE,
      { imageConfig: { aspectRatio: "16:9" } }
    );
    const part = res.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : null;
  } catch { return null; }
};

export const generateSeoSuggestions = async (title: string, content: string) => {
  try {
    const res = await generateContent(
      `Generate SEO meta description (max 160 chars) and keywords for a blog post.\nTitle: ${title}\nContent: ${content.substring(0, 1000)}`,
      MODELS.FLASH,
      {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            metaDescription: { type: Type.STRING },
            metaKeywords: { type: Type.STRING }
          },
          required: ["metaDescription", "metaKeywords"]
        }
      }
    );
    return JSON.parse(res.text || '{}');
  } catch (e) {
    console.error(e);
    return null;
  }
};

export const getLatestWorkersCompNews = async (): Promise<NewsItem[] | null> => {
  const cached = getDailyNews();
  if (cached) return cached.newsItems;

  try {
    const res = await generateContent(
      "List 6 major CA Workers' Comp news stories today. Focus on case law updates, regulatory changes, or significant workplace safety trends. Return JSON array of {title, summary, url}.",
      MODELS.PRIMARY,
      {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            newsItems: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: { title: { type: Type.STRING }, summary: { type: Type.STRING }, url: { type: Type.STRING } }
              }
            }
          }
        }
      }
    );
    const items = JSON.parse(res.text || '{}').newsItems;
    if (items) setDailyNews(items);
    return items;
  } catch { return null; }
};

