export const checkAndGenerateWeeklyPost = async () => {
  const posts = getAllBlogPosts();
  if (!posts.length) return;
  const diff = (Date.now() - new Date(posts[0].publishedDate).getTime()) / (1000 * 3600 * 24);
  if (diff > 7) {
    try {
      const res = await generateContent("Generate a high-quality CA workers comp blog post including SEO metadata. JSON format.", MODELS.PRIMARY, {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: { 
            title: { type: Type.STRING }, 
            slug: { type: Type.STRING }, 
            excerpt: { type: Type.STRING }, 
            content: { type: Type.STRING }, 
            category: { type: Type.STRING },
            metaDescription: { type: Type.STRING },
            metaKeywords: { type: Type.STRING }
          },
          required: ["title", "slug", "excerpt", "content", "category", "metaDescription", "metaKeywords"]
        }
      });
      const data = JSON.parse(res.text || '{}');
      const img = await generateImageForPost(data.title);
      addBlogPost({ 
        ...data, 
        imageUrl: img || 'https://picsum.photos/800/600', 
        publishedDate: new Date().toISOString().split('T')[0], 
        citations: [] 
      });
    } catch (e) { console.error(e); }
  }
};

