      // Simulate network delay for better UX
      await new Promise(resolve => setTimeout(resolve, 1000));

      try {
        addInquiry({
          name: formData.name,
          phone: formData.phone,
          email: formData.email,
          injuryDate: formData.injury_date,
          appointmentRequestDate: formData.appointment_date,
          message: formData.message,
          howDidYouHear: formData.how_did_you_hear
        });
        setIsSubmitted(true);
      } catch (err) {
        setError('There was an error submitting your inquiry. Please try again later.');
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleBack = () => {
    setError('');
    setStep(s => s - 1);
