import AnimatedComponent from '../components/AnimatedComponent';
import { addInquiry } from '../services/inquiryService';

interface Question {
    id: string;
    text: string;
    options: { label: string; value: string; next?: string; score: number }[];
}

const questions: Question[] = [
    {
        id: 'type',
        text: 'What type of injury did you sustain?',
        options: [
            { label: 'Specific Accident (e.g., fall, crash)', value: 'specific', next: 'reported', score: 10 },
            { label: 'Repetitive Strain (e.g., carpal tunnel)', value: 'repetitive', next: 'duration', score: 8 },
