            { label: 'Other / Not Sure', value: 'other', next: 'reported', score: 5 }
        ]
    },
    {
        id: 'duration',
        text: 'How long have you been experiencing symptoms?',
        options: [
            { label: 'Less than 1 month', value: 'recent', next: 'reported', score: 5 },
            { label: '1 - 6 months', value: 'medium', next: 'reported', score: 8 },
            { label: 'Over 6 months', value: 'long', next: 'reported', score: 10 }
        ]
    },
    {
        id: 'reported',
        text: 'Have you reported the injury to your employer?',
        options: [
            { label: 'Yes, immediately', value: 'yes-immediate', next: 'medical', score: 10 },
            { label: 'Yes, but later', value: 'yes-late', next: 'medical', score: 5 },
            { label: 'No, not yet', value: 'no', next: 'medical', score: 2 }
        ]
    },
    {
