            { label: 'No, I need help finding a doctor', value: 'none', next: 'work_status', score: 5 }
        ]
    },
    {
        id: 'work_status',
        text: 'Are you currently missing work due to your injury?',
        options: [
            { label: 'Yes, I am completely off work', value: 'off', score: 15 },
            { label: 'Yes, I am on modified duties', value: 'modified', score: 10 },
            { label: 'No, I am still working regular duties', value: 'working', score: 5 }
        ]
    }
];

const Viability: React.FC = () => {
    const [currentStep, setCurrentStep] = useState(0);
    const [answers, setAnswers] = useState<Record<string, string>>({});
    const [score, setScore] = useState(0);
    const [isFinished, setIsFinished] = useState(false);
    const [isSubmitted, setIsSubmitted] = useState(false);
    const [contactInfo, setContactInfo] = useState({ name: '', email: '', phone: '' });
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleOptionSelect = (option: typeof questions[0]['options'][0]) => {
        const nextScore = score + option.score;
        setScore(nextScore);
        setAnswers(prev => ({ ...prev, [questions[currentStep].id]: option.label }));

        if (currentStep < questions.length - 1) {
            setTimeout(() => setCurrentStep(currentStep + 1), 300); // Slight delay for better UX
        } else {
            setTimeout(() => setIsFinished(true), 300);
        }
    };

    const handleLeadSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        const message = `Case Viability Check Summary:\n${Object.entries(answers).map(([k, v]) => `${k}: ${v}`).join('\n')}\nEstimated Viability Score: ${score}/53`;

        await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate net request

        await addInquiry({
            ...contactInfo,
            message,
            howDidYouHear: 'Viability Assessment Tool'
        });
        setIsSubmitting(false);
        setIsSubmitted(true);
    };

    const currentQuestion = questions[currentStep];
    const progress = ((currentStep) / questions.length) * 100;

    return (
        <div className="bg-gray-50 min-h-screen py-20">
            <div className="container mx-auto px-4 max-w-2xl">
                <AnimatedComponent>
                    <div className="text-center mb-12">
                        <span className="text-[#FFB703] font-bold text-sm tracking-widest uppercase">Free Case Evaluation Tool</span>
                        <h1 className="text-3xl md:text-5xl font-extrabold text-[#0F1E4A] mt-2">Do I Have a Case?</h1>
                        <p className="mt-4 text-lg text-gray-600">Answer 5 simple questions for a preliminary assessment of your workers' compensation claim potential.</p>
                    </div>
                </AnimatedComponent>

                {!isFinished ? (
                    <div className="bg-white rounded-2xl shadow-xl p-8 border-t-8 border-[#FFB703] transition-all">
                        <div className="mb-8">
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-xs font-bold text-gray-400 uppercase">Question {currentStep + 1} of {questions.length}</span>
                                <span className="text-xs font-bold text-[#FFB703]">{Math.round(progress)}% Complete</span>
                            </div>
                            <div className="w-full bg-gray-100 h-2 rounded-full overflow-hidden">
                                <div className="bg-[#FFB703] h-full rounded-full transition-all duration-500 ease-out" style={{ width: `${progress}%` }}></div>
                            </div>
                        </div>

                        <div key={currentQuestion.id} className="animate-fade-in">
                            <h2 className="text-2xl font-bold text-[#0F1E4A] mb-8 leading-snug">{currentQuestion.text}</h2>

                            <div className="space-y-4">
                                {currentQuestion.options.map((option, idx) => (
                                    <button
                                        key={idx}
                                        onClick={() => handleOptionSelect(option)}
                                        className="w-full text-left p-5 rounded-xl border-2 border-gray-100 hover:border-[#FFB703] hover:bg-yellow-50 hover:shadow-md transition-all font-semibold text-gray-700 flex justify-between items-center group duration-200"
                                    >
                                        {option.label}
                                        <svg className="w-5 h-5 text-gray-300 group-hover:text-[#FFB703] transform group-hover:translate-x-1 transition-all" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : !isSubmitted ? (
                    <div className="bg-white rounded-2xl shadow-xl p-8 md:p-12 border-t-8 border-green-500 animate-fade-in text-center">
                        <div className="inline-block p-4 rounded-full bg-green-50 mb-6 animate-pulse">
                            <svg className="w-12 h-12 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        </div>
                        <h2 className="text-3xl font-black text-[#0F1E4A] mb-4">Assessment Complete</h2>
                        <p className="text-gray-600 mb-8 text-lg">Based on your answers, your case shows <strong className="text-green-600">strong potential for compensation</strong>. To protect your rights, we recommend a free attorney review immediately.</p>

                        <form onSubmit={handleLeadSubmit} className="space-y-4 text-left max-w-md mx-auto">
                            <div>
                                <label className="block text-sm font-bold text-[#0F1E4A] mb-1">Full Name</label>
                                <input 
                                    type="text" required 
                                    className="w-full border border-gray-300 rounded-lg p-3 focus:ring-2 focus:ring-[#FFB703] outline-none transition-shadow"
                                    value={contactInfo.name}
                                    onChange={e => setContactInfo({...contactInfo, name: e.target.value})}
                                    placeholder="Jane Doe"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-[#0F1E4A] mb-1">Phone Number</label>
                                <input 
                                    type="tel" required 
                                    className="w-full border border-gray-300 rounded-lg p-3 focus:ring-2 focus:ring-[#FFB703] outline-none transition-shadow"
                                    value={contactInfo.phone}
                                    onChange={e => setContactInfo({...contactInfo, phone: e.target.value})}
                                    placeholder="(555) 123-4567"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-[#0F1E4A] mb-1">Email Address</label>
                                <input 
                                    type="email" required 
                                    className="w-full border border-gray-300 rounded-lg p-3 focus:ring-2 focus:ring-[#FFB703] outline-none transition-shadow"
                                    value={contactInfo.email}
                                    onChange={e => setContactInfo({...contactInfo, email: e.target.value})}
                                    placeholder="jane@example.com"
                                />
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmitting}
                                className="w-full bg-[#FFB703] text-[#0F1E4A] font-bold py-4 rounded-xl hover:bg-yellow-400 transition-all shadow-lg mt-6 transform hover:scale-[1.02] active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isSubmitting ? 'Submitting...' : 'Get My Free Case Review'}
                            </button>
                            <p className="text-xs text-gray-400 text-center mt-4">
                                Your information is confidential. Submitting this form does not create an attorney-client relationship.
                            </p>
                        </form>
                    </div>
                ) : (
                    <div className="bg-white rounded-2xl shadow-xl p-12 border border-gray-100 text-center animate-fade-in">
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <svg className="w-10 h-10 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                        </div>
                        <h2 className="text-3xl font-black text-[#0F1E4A] mb-4">Request Received!</h2>
                        <p className="text-gray-600 mb-8 text-lg">Our legal team is reviewing your assessment right now. We will contact you at <strong>{contactInfo.phone}</strong> shortly to discuss your case strategy.</p>
                        <button 
                            onClick={() => window.location.reload()} 
                            className="text-[#0F1E4A] font-bold underline hover:text-[#FFB703] transition-colors"
                        >
                            Start Over
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

