import type { Appointment } from '../types';
import { sendAdminNotification } from './emailService';

const STORAGE_KEY = 'jla_appointments_db';

const loadAppointments = (): Appointment[] => {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) return JSON.parse(stored);
  } catch (e) {
    // ignore error
  }

  // Default mock data if storage is empty
  return [
    {
      id: '1',
      name: 'Maria Rodriguez',
      date: new Date().toISOString().split('T')[0],
      time: '10:00',
      reason: 'Initial Consultation - Back Injury'
    },
    {
      id: '2',
      name: 'John Smith',
      date: new Date(Date.now() + 86400000).toISOString().split('T')[0],
      time: '14:30',
      reason: 'Follow-up on Claim Denial'
    }
  ];
};

const saveAppointments = (appointments: Appointment[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(appointments));
};

let appointments: Appointment[] = loadAppointments();

export const getAppointments = (): Appointment[] => {
  return [...appointments].sort((a, b) => {
      const dateA = new Date(`${a.date}T${a.time}`);
      const dateB = new Date(`${b.date}T${b.time}`);
      return dateA.getTime() - dateB.getTime();
  });
};

export const addAppointment = (appt: Omit<Appointment, 'id'>): Appointment => {
  const newAppt = {
    ...appt,
    id: Math.random().toString(36).substring(2, 9)
  };
  appointments.push(newAppt);
  saveAppointments(appointments);

  sendAdminNotification(
    "New Appointment Scheduled",
    `A new appointment has been added to the calendar.\n\nClient: ${newAppt.name}\nDate: ${newAppt.date}\nTime: ${newAppt.time}\nReason: ${newAppt.reason}`
  );

  return newAppt;
};

export const deleteAppointment = (id: string): void => {
  appointments = appointments.filter(a => a.id !== id);
  saveAppointments(appointments);
};

import type { FormSubmission, FormType } from '../types';
import { sendAdminNotification } from './emailService';

const STORAGE_KEY = 'jla_forms_db';

const loadSubmissions = (): FormSubmission[] => {
    try {
        const stored = localStorage.getItem(STORAGE_KEY);
        return stored ? JSON.parse(stored) : [];
    } catch(e) {
        return [];
    }
};

const saveSubmissions = (subs: FormSubmission[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(subs));
};

let submissions: FormSubmission[] = loadSubmissions();

export const getFormSubmissions = (): FormSubmission[] => {
    return [...submissions].sort((a, b) => new Date(b.submittedAt).getTime() - new Date(a.submittedAt).getTime());
};

export const submitForm = (type: FormType, data: Record<string, any>): FormSubmission => {
    const submission: FormSubmission = {
        id: Math.random().toString(36).substring(2, 9),
        type,
        submittedAt: new Date().toISOString(),
        data,
        status: 'new'
    };

    submissions.push(submission);
    saveSubmissions(submissions);

    // Format data for email
    const formattedData = Object.entries(data)
        .map(([key, value]) => `${key}: ${value}`)
        .join('\n');

    const typeLabel = type.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');

    sendAdminNotification(
        `New ${typeLabel} Intake Form Submission`,
        `A new client intake form has been submitted via the Services portal.\n\nType: ${typeLabel}\nDate: ${new Date().toLocaleString()}\n\n--- Form Data ---\n${formattedData}`
    );

    return submission;
};

export const deleteFormSubmission = (id: string): void => {
    submissions = submissions.filter(s => s.id !== id);
    saveSubmissions(submissions);
};

