// --- CountUp Component for Animated Numbers ---
const CountUp: React.FC<{ value: string }> = ({ value }) => {
    const [displayValue, setDisplayValue] = useState(0);
    const ref = useRef<HTMLSpanElement>(null);
    const [setElements, entries] = useIntersectionObserver({ threshold: 0.5, triggerOnce: true });

    // Extract number from string (e.g. "$1,250,000" -> 1250000)
    const numericValue = parseInt(value.replace(/[^0-9]/g, ''), 10);
    const isCurrency = value.includes('$');
    const suffix = value.includes('+') ? '+' : '';

    useEffect(() => {
        if (ref.current) setElements([ref.current]);
    }, [setElements]);

    useEffect(() => {
        const entry = entries[0];
        if (entry && entry.isIntersecting && !isNaN(numericValue)) {
            let start = 0;
            const end = numericValue;
            const duration = 2000; // 2 seconds
            const startTime = performance.now();

            const animate = (currentTime: number) => {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);

                // Ease out quart
                const ease = 1 - Math.pow(1 - progress, 4);

                const current = Math.floor(start + (end - start) * ease);
                setDisplayValue(current);

                if (progress < 1) {
                    requestAnimationFrame(animate);
                }
            };
            requestAnimationFrame(animate);
        } else if (isNaN(numericValue)) {
            // Fallback for non-numeric outcomes (e.g. "Full Coverage")
            setDisplayValue(-1); 
        }
    }, [entries, numericValue]);

    if (displayValue === -1) return <span>{value}</span>;

    const formatted = new Intl.NumberFormat('en-US', {
        style: isCurrency ? 'currency' : 'decimal',
        currency: 'USD',
        maximumFractionDigits: 0
    }).format(displayValue);

    return <span ref={ref}>{formatted}{suffix}</span>;
};

