                className="mt-6 text-[#FFB703] font-bold hover:underline px-4 py-2"
              >
                Clear all filters
              </button>
            </div>
          )}
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="mt-16 flex flex-col sm:flex-row justify-center items-center gap-4 sm:space-x-2">
             <div className="flex justify-between w-full sm:w-auto gap-4">
                <button 
                    onClick={() => paginate(currentPage - 1)} 
                    disabled={currentPage === 1} 
                    className="flex-1 sm:flex-none px-6 py-3 bg-gray-100 border border-gray-200 rounded-lg hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed font-semibold text-gray-700 transition-colors focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:ring-offset-2 flex items-center justify-center min-w-[120px]"
                    aria-label="Go to previous page"
                >
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                Previous
                </button>

                {/* Mobile Page Indicator */}
                 <span className="sm:hidden flex items-center justify-center font-bold text-gray-600 whitespace-nowrap">
                    Page {currentPage} of {totalPages}
                </span>

                <button 
                    onClick={() => paginate(currentPage + 1)} 
                    disabled={currentPage === totalPages} 
                    className="flex-1 sm:flex-none px-6 py-3 bg-gray-100 border border-gray-200 rounded-lg hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed font-semibold text-gray-700 transition-colors focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:ring-offset-2 flex items-center justify-center min-w-[120px]"
                    aria-label="Go to next page"
                >
                Next
                <svg className="w-4 h-4 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                </button>
            </div>

            {/* Desktop Page Numbers */}
            <div className="hidden sm:flex items-center space-x-2">
                {pageNumbers.map(number => (
                <button 
                    key={number} 
                    onClick={() => paginate(number)} 
                    className={`flex items-center justify-center h-10 w-10 rounded-full transition-all duration-200 font-medium ${currentPage === number ? 'bg-[#0F1E4A] text-white shadow-md transform scale-110' : 'bg-white border border-gray-300 text-gray-600 hover:bg-gray-50 hover:border-gray-400 hover:text-[#0F1E4A]'}`}
                    aria-label={`Go to page ${number}`}
                    aria-current={currentPage === number ? 'page' : undefined}
                >
                    {number}
                </button>
                ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

