const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const [currentPostSlug, setCurrentPostSlug] = useState<string | null>(null);
  const [selectedFormType, setSelectedFormType] = useState<FormType | null>(null);
  const [showCookiePolicy, setShowCookiePolicy] = useState(false);
  const [showConsentBanner, setShowConsentBanner] = useState(() => !localStorage.getItem('cookie_consent'));
  const [isMobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Initialize weekly automation
  useEffect(() => {
    checkAndGenerateWeeklyPost();
  }, []);

  // Handle Browser History (Back/Forward buttons)
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (event.state) {
        setCurrentPage(event.state.page || 'home');
        setCurrentPostSlug(event.state.slug || null);
        setSelectedFormType(event.state.formType || null);
      } else {
        // Fallback for initial load if no state
        setCurrentPage('home');
      }
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  // Use custom hook for SEO/Meta
  useMeta(currentPage, currentPostSlug);

  const navigate = useCallback((page: Page, slug?: string | null, formType?: FormType | null) => {
    // Update State
    setCurrentPage(page);
    setCurrentPostSlug(slug || null);
    setSelectedFormType(formType || null);
    setMobileMenuOpen(false);

    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });

    // Push to History
    const state = { page, slug, formType };
    // Construct a pseudo-URL for aesthetics (optional, but good for UX)
    let url = `/${page}`;
    if (page === 'home') url = '/';
    if (slug) url = `/blog/${slug}`;

    try {
      window.history.pushState(state, '', url);
    } catch (e) {
      // In some sandboxed environments (like AI Studio preview), pushState might be blocked.
      // We catch the error to ensure the app doesn't crash, allowing navigation via state update.
      console.warn("History pushState blocked:", e);
    }
  }, []);

  // Wrappers for specific navigation actions to maintain prop compatibility
  const handlePageNavigate = (page: Page) => navigate(page);
  const handlePostNavigate = (slug: string) => navigate('blogPost', slug);
  const handleFormNavigate = (formType: FormType) => navigate('form-viewer', null, formType);

  // Consolidate ActivePageContent
  const ActivePageContent = useMemo(() => {
    const pages: Record<Page, React.ReactNode> = {
      'home': <Homepage navigate={handlePageNavigate} navigateToPost={handlePostNavigate} />,
      'practice-areas': <PracticeAreas navigate={handlePageNavigate} />,
      'case-results': <CaseResults navigate={handlePageNavigate} />,
      'tools': <Tools navigate={handlePageNavigate} />,
      'team': <Team />,
      'faqs': <FAQs />,
      'contact': <Contact />,
      'blog': <Blog navigateToPost={handlePostNavigate} />,
      'blogPost': <BlogPostPage slug={currentPostSlug} navigate={handlePageNavigate} navigateToPost={handlePostNavigate} />,
      'services': <Services navigate={handlePageNavigate} navigateToForm={handleFormNavigate} />,
      'form-viewer': <FormPage formType={selectedFormType} navigate={handlePageNavigate} />,
      'news': <News />,
      'weekly-analysis': <WeeklyAnalysis />,
      'our-method': <OurMethod navigate={handlePageNavigate} />,
      'sitemap': <Sitemap />,
      'admin': <Admin />,
      'terms-of-use': <TermsOfUse />,
      'viability': <Viability />
    };

    return pages[currentPage] || pages['home'];
  }, [currentPage, currentPostSlug, selectedFormType, navigate]);

  return (
    <div className="bg-gray-50 min-h-screen flex flex-col selection:bg-[#FFB703]/30">
      <Header 
        navigate={handlePageNavigate} 
        currentPage={currentPage}
        isMobileMenuOpen={isMobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen} 
      />

      <main className={`flex-grow transition-all duration-300 ${isMobileMenuOpen ? 'blur-sm grayscale pointer-events-none' : ''}`}>
        <Suspense fallback={<LoadingSpinner />}>
          {ActivePageContent}
        </Suspense>
      </main>

      <Footer navigate={handlePageNavigate} setShowCookiePolicy={setShowCookiePolicy} />

      <GeminiChatbot navigate={handlePageNavigate} currentPage={currentPage} />

      {showCookiePolicy && <CookiePolicy onClose={() => setShowCookiePolicy(false)} />}

      {showConsentBanner && (
        <CookieConsentBanner 
          onAccept={() => { localStorage.setItem('cookie_consent', 'true'); setShowConsentBanner(false); }}
          onDecline={() => { localStorage.setItem('cookie_consent', 'false'); setShowConsentBanner(false); }}
          onShowPolicy={() => setShowCookiePolicy(true)}
        />
      )}
    </div>
  );
};

export default App;

