interface BodyPartSelectorProps {
    selectedParts: string[];
    onSelectPart: (part: string) => void;
}

const BodyDiagram: React.FC<BodyPartSelectorProps> = ({ selectedParts, onSelectPart }) => {
    const [view, setView] = useState<'front' | 'back'>('front');
    const [hoveredPart, setHoveredPart] = useState<string | null>(null);

    const isSelected = (id: string) => selectedParts.includes(id);

    const Path: React.FC<{ id: string, d: string, label: string }> = ({ id, d, label }) => {
        const active = isSelected(id);
        const hovered = hoveredPart === id;

        return (
            <g 
                onClick={() => onSelectPart(id)} 
                onMouseEnter={() => setHoveredPart(id)}
                onMouseLeave={() => setHoveredPart(null)}
                className="cursor-pointer transition-all duration-300"
            >
                <path 
                    d={d} 
                    className={`transition-all duration-300 stroke-[1.5] ${
                        active 
                            ? 'fill-[#FFB703] stroke-[#0F1E4A] filter drop-shadow-[0_0_8px_rgba(255,183,3,0.6)]' 
                            : hovered 
                                ? 'fill-blue-200 stroke-[#0F1E4A]' 
                                : 'fill-gray-100 stroke-gray-300 hover:stroke-gray-400'
                    }`} 
                />
                {/* Labels on Hover */}
                {(hovered || active) && (
                    <text 
                        x="150" 
                        y="30" 
                        textAnchor="middle" 
                        className="text-xs font-black fill-[#0F1E4A] uppercase tracking-wider pointer-events-none"
                    >
                        {label}
                    </text>
                )}
            </g>
        );
    };

    return (
