// --- Calculation Logic ---

const getTDRates = (doi: Date): { min: number, max: number } => {
    const year = doi.getFullYear();
    if (year >= 2024) return { min: 242.86, max: 1619.15 };
    if (year >= 2023) return { min: 242.86, max: 1619.15 };
    if (year >= 2022) return { min: 230.95, max: 1539.71 };
    if (year >= 2021) return { min: 203.44, max: 1356.31 };
    if (year >= 2020) return { min: 194.91, max: 1299.43 };
    return { min: 187.71, max: 1251.38 };
};

const getPDRates = (doi: Date): { weeklyMax: number, lifePensionMin: number, lifePensionMax: number } => {
    const year = doi.getFullYear();
    if (year >= 2014) return { weeklyMax: 290, lifePensionMin: 162.69, lifePensionMax: 277.78 };
    if (year === 2013) return { weeklyMax: 270, lifePensionMin: 155.67, lifePensionMax: 251.53 };
    return { weeklyMax: 230, lifePensionMin: 139.69, lifePensionMax: 226.54 };
}

// Combined Values Equation (CVC) Logic: A + B(1 - A)
const calculateCombinedRating = (ratings: number[]): number => {
    if (ratings.length === 0) return 0;
    // Sort descending to process largest first
    const sorted = [...ratings].sort((a, b) => b - a);
    let combined = sorted[0] / 100;

    for (let i = 1; i < sorted.length; i++) {
        const next = sorted[i] / 100;
        combined = combined + next * (1 - combined);
    }

    return Math.round(combined * 100);
};

const calculateBenefits = (aww: number, rating: number, doi: Date, apportionment: number) => {
    const tdRates = getTDRates(doi);
    const pdRates = getPDRates(doi);

    // 1. Temporary Disability
    const weeklyTD = Math.max(tdRates.min, Math.min(aww * (2/3), tdRates.max));
    const maxTotalTD = weeklyTD * 104;

    // 2. Permanent Disability
    let pdWeeks = 0;
    if (rating > 0) {
        if (rating < 10) pdWeeks = rating * 3;
        else if (rating < 70) {
            const chart: { [key: number]: number[] } = {
                10: [27, 4], 15: [47, 5], 20: [67, 5], 25: [87, 5],
                30: [110.25, 6], 40: [155.25, 6], 50: [210.25, 7], 60: [275.25, 7], 70: [340.25, 8]
            };
            const base = Math.floor((rating - 0.25) / 5) * 5;
            const key = base < 10 ? 10 : (base < 30 ? base : Math.floor(base/10)*10); 
            const values = chart[key] || chart[10]; 
            if(values) {
                pdWeeks = values[0] + ((rating - (key - 0.25)) * values[1]); 
            }
        } else { // 70-99.75
            pdWeeks = 340.25 + ((rating - 69.75) * 8);
        }
    }
    pdWeeks = Math.max(0, pdWeeks);
    const weeklyPD = Math.min(aww * (2/3), pdRates.weeklyMax);
    const grossTotalPD = pdWeeks * weeklyPD;

    // 3. Life Pension
    let grossWeeklyLP = 0;
    if (rating >= 70) {
        const lp = (rating - 70) * 0.015 * Math.min(aww, 515.38); 
        grossWeeklyLP = lp; 
    }

    // 4. Apportionment
    const apportionmentAmountPD = grossTotalPD * (apportionment / 100);
    const netTotalPD = grossTotalPD - apportionmentAmountPD;
    const apportionmentAmountLP = grossWeeklyLP * (apportionment / 100);
    const netWeeklyLP = grossWeeklyLP - apportionmentAmountLP;

    return {
        weeklyTD,
        maxTotalTD,
        pdWeeks: Math.round(pdWeeks * 100) / 100,
        weeklyPD,
        grossTotalPD,
        apportionmentAmountPD,
        netTotalPD,
        grossWeeklyLP,
        apportionmentAmountLP,
        netWeeklyLP
    };
};

const GaugeMeter: React.FC<{ value: number }> = ({ value }) => {
    // Value is typically between 0 and 200,000 for standard cases (excluding Life Pension)
    // Scale it to 0-100% for the bar visual
    const percentage = Math.min(Math.max((value / 150000) * 100, 5), 100); 

    return (
        <div className="w-full mt-6 mb-2">
            <div className="flex justify-between text-xs text-blue-200 mb-2 uppercase font-bold tracking-wider">
