import React, { useState, useEffect, useMemo } from 'react';
import { getBlogPostBySlug, getRelatedPosts } from '../services/contentService';
import type { BlogPost, Page } from '../types';
import { injectTooltipsToHtml } from '../lib/tooltipHelpers';
import TextWithTooltips from '../components/TextWithTooltips';
import AnimatedComponent from '../components/AnimatedComponent';

interface BlogPostProps {
  slug: string | null;
  navigate: (page: Page) => void;
  navigateToPost: (slug: string) => void;
}

const BlogPostPage: React.FC<BlogPostProps> = ({ slug, navigate, navigateToPost }) => {
  const [post, setPost] = useState<BlogPost | null>(null);
  const [relatedPosts, setRelatedPosts] = useState<BlogPost[]>([]);
  const [processedContent, setProcessedContent] = useState<string>('');
  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    if (slug) {
      const foundPost = getBlogPostBySlug(slug);
      if (foundPost) {
        setPost(foundPost);
        setRelatedPosts(getRelatedPosts(foundPost));
      } else {
        setPost(null);
      }
    }
  }, [slug]);

  useEffect(() => {
    const handleScroll = () => {
      const totalHeight = document.documentElement.scrollHeight - window.innerHeight;
      const progress = (window.pageYOffset / totalHeight) * 100;
      setScrollProgress(progress);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (post) {
      setProcessedContent(injectTooltipsToHtml(post.content));

      // Structured Data for the article
      const scriptId = 'blog-post-structured-data';
      let script = document.getElementById(scriptId) as HTMLScriptElement | null;
      if (!script) {
        script = document.createElement('script');
        script.id = scriptId;
        script.type = 'application/ld+json';
        document.head.appendChild(script);
      }
      script.innerHTML = JSON.stringify({
        '@context': 'https://schema.org',
        '@type': 'BlogPosting',
        'headline': post.title,
        'image': post.imageUrl,
        'datePublished': post.publishedDate,
        'author': {
          '@type': 'Organization',
          'name': 'Jimenez Law APC'
        },
        'publisher': {
          '@type': 'Organization',
          'name': 'Jimenez Law APC',
          'logo': {
            '@type': 'ImageObject',
            'url': `${window.location.origin}/logo.png`
          }
        },
        'description': post.metaDescription,
        'keywords': post.metaKeywords
      });

      return () => {
        const existingScript = document.getElementById(scriptId);
        if (existingScript) {
          existingScript.remove();
        }
      }
    }
  }, [post]);

  const readingTime = useMemo(() => {
    if (!post?.content) return 0;
    const wordsPerMinute = 225;
    const words = post.content.replace(/<[^>]*>?/gm, '').split(/\s+/).length;
    return Math.ceil(words / wordsPerMinute);
  }, [post?.content]);

  if (!post) {
    return (
      <div className="flex justify-center items-center py-20 min-h-[50vh]">
        <div className="text-center">
          <h2 className="text-2xl font-bold">Post not found</h2>
          <button onClick={() => navigate('blog')} className="mt-4 font-semibold text-[#FFB703] hover:text-yellow-500">
            &larr; Back to Blog
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white min-h-screen">
      {/* Reading Progress Bar */}
      <div 
        className="fixed top-0 left-0 h-1.5 bg-[#FFB703] z-[60] transition-all duration-100 ease-out" 
        style={{ width: `${scrollProgress}%` }}
        aria-hidden="true"
      />

      <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-10 md:py-16 max-w-4xl">
        <div className="mb-10 md:mb-12">
             <button 
                onClick={() => navigate('blog')} 
                className="inline-flex items-center text-gray-500 hover:text-[#0F1E4A] font-semibold transition-all group py-2 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:ring-offset-2"
                aria-label="Return to blog list"
            >
                <div className="bg-gray-100 p-2 rounded-full mr-3 group-hover:bg-[#FFB703] transition-colors group-hover:shadow-md">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 transform group-hover:-translate-x-1 transition-transform text-[#0F1E4A]" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
                    </svg>
                </div>
                Back to Articles
            </button>
        </div>

        <AnimatedComponent>
          <article className="animate-fade-in">
            <header className="mb-10 md:mb-14">
              <div className="flex flex-wrap items-center justify-center gap-3 mb-6">
                <span className="px-4 py-1.5 bg-[#0F1E4A] text-white text-xs font-bold uppercase tracking-widest rounded-full shadow-sm">
                  {post.category}
                </span>
                <span className="text-gray-300">|</span>
                <div className="flex items-center text-gray-500 text-sm font-medium">
                  <svg className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  {readingTime} min read
                </div>
              </div>

              <h1 className="text-4xl sm:text-5xl md:text-6xl font-extrabold text-[#0F1E4A] leading-tight text-center tracking-tight mb-6">
                {post.title}
              </h1>

              <div className="flex items-center justify-center text-sm text-gray-500 font-medium">
                <time dateTime={post.publishedDate}>
                  {new Date(post.publishedDate).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
                </time>
                <span className="mx-3">•</span>
                <span>By Jimenez Law APC Editorial Team</span>
              </div>
            </header>

            <div className="rounded-2xl overflow-hidden shadow-2xl mb-12 md:mb-16 border border-gray-100 ring-8 ring-gray-50/50">
                <img 
                src={post.imageUrl} 
                alt={post.title} 
                className="w-full h-auto max-h-[550px] object-cover hover:scale-[1.01] transition-transform duration-700" 
                />
            </div>

            {/* Prose Content - Optimized for readability */}
            <div className="prose prose-slate lg:prose-xl max-w-none text-gray-800 leading-[1.8] 
                prose-headings:text-[#0F1E4A] prose-headings:font-extrabold prose-headings:tracking-tight
                prose-h2:text-3xl prose-h2:mt-12 prose-h2:mb-6 prose-h2:border-l-4 prose-h2:border-[#FFB703] prose-h2:pl-4
                prose-h3:text-2xl prose-h3:mt-10 prose-h3:mb-4
                prose-p:mb-8 prose-p:text-lg
                prose-a:text-[#0F1E4A] prose-a:font-bold prose-a:decoration-[#FFB703] prose-a:underline-offset-4 prose-a:decoration-2 hover:prose-a:bg-[#FFB703]/10
                prose-li:text-lg prose-li:marker:text-[#FFB703]
                prose-img:rounded-2xl prose-img:shadow-xl prose-img:my-12
                prose-blockquote:border-l-4 prose-blockquote:border-[#FFB703] prose-blockquote:bg-gray-50 prose-blockquote:py-2 prose-blockquote:px-8 prose-blockquote:rounded-r-xl prose-blockquote:italic prose-blockquote:text-xl prose-blockquote:text-gray-700
                " 
                dangerouslySetInnerHTML={{ __html: processedContent }} />

            {post.citations && post.citations.length > 0 && (
              <div className="mt-16 pt-8 border-t border-gray-100 bg-gray-50 rounded-2xl p-8 shadow-inner">
                  <h3 className="text-xl font-bold text-[#0F1E4A] mb-6 flex items-center">
                    <svg className="w-6 h-6 mr-3 text-[#FFB703]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                    </svg>
                    Legal References & Sources
                  </h3>
                  <ul className="space-y-4">
                      {post.citations.map((citation, idx) => (
                          <li key={idx} className="flex items-start group">
                              <span className="flex-shrink-0 w-6 h-6 bg-[#0F1E4A] text-[#FFB703] rounded-full flex items-center justify-center text-xs font-bold mr-4 mt-0.5 shadow-sm">
                                {idx + 1}
                              </span>
                              <a 
                                href={citation.uri} 
                                target="_blank" 
                                rel="noopener noreferrer" 
                                className="text-gray-600 hover:text-[#0F1E4A] transition-colors leading-relaxed border-b border-transparent hover:border-[#FFB703]"
                              >
                                {citation.title}
                              </a>
                          </li>
                      ))}
                  </ul>
              </div>
            )}
          </article>
        </AnimatedComponent>

        {/* Author Bio Section (Static for now but improves "readability" feel) */}
        <AnimatedComponent>
          <div className="mt-16 p-8 border border-gray-100 rounded-2xl bg-white shadow-sm flex flex-col md:flex-row items-center gap-6">
            <img src="/logo.png" alt="Jimenez Law APC" className="w-20 h-20 bg-[#0F1E4A] rounded-full p-2" />
            <div>
              <h4 className="text-lg font-bold text-[#0F1E4A] mb-1">About Jimenez Law, APC</h4>
              <p className="text-gray-600 text-sm leading-relaxed">
                Our firm is dedicated to educating the public about their rights under California workers' compensation law. Our team works tirelessly to ensure that every injured worker receives the medical care and benefits they are legally entitled to.
              </p>
            </div>
          </div>
        </AnimatedComponent>

        {/* Related Posts Section */}
        {relatedPosts.length > 0 && (
          <AnimatedComponent>
            <aside className="mt-24 pt-16 border-t border-gray-100">
              <div className="flex items-center justify-between mb-12">
                <h2 className="text-3xl font-extrabold text-[#0F1E4A] tracking-tight">
                  Continue Reading
                </h2>
                <button 
                  onClick={() => navigate('blog')}
                  className="text-sm font-bold text-gray-500 hover:text-[#FFB703] transition-colors uppercase tracking-widest"
                >
                  View all posts
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                {relatedPosts.map(related => (
                  <div 
                    key={related.id} 
                    className="bg-white border border-gray-100 rounded-2xl shadow-sm overflow-hidden flex flex-col transition-all duration-300 hover:shadow-xl hover:-translate-y-1 group h-full cursor-pointer"
