import React, { useState } from 'react';
import { addInquiry } from '../services/inquiryService';
import AnimatedComponent from '../components/AnimatedComponent';

const ProgressBar: React.FC<{ step: number; totalSteps: number }> = ({ step, totalSteps }) => (
  <div className="w-full bg-gray-200 rounded-full h-2.5 mb-8">
    <div 
      className="bg-[#FFB703] h-2.5 rounded-full transition-all duration-500" 
      style={{ width: `${(step / totalSteps) * 100}%` }}
    ></div>
  </div>
);

const Label: React.FC<{ htmlFor: string; required?: boolean; optional?: boolean; children: React.ReactNode }> = ({ htmlFor, required, optional, children }) => (
  <label htmlFor={htmlFor} className="block text-sm font-bold text-[#0F1E4A] mb-2 flex justify-between items-center">
    <span>
      {children}
      {required && <span className="text-red-500 ml-1" title="Required">*</span>}
    </span>
    {optional && <span className="text-gray-400 font-normal italic text-xs">Optional</span>}
  </label>
);

const Contact: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    injury_date: '',
    appointment_date: '',
    message: '',
    how_did_you_hear: ''
  });
  const [step, setStep] = useState(1);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFormSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (step === 1) {
      if (!formData.name.trim() || !formData.phone.trim() || !formData.email.trim()) {
        setError('Please fill out all required contact fields.');
        return;
      }
      setStep(2);
    } else if (step === 2) {
      if (isSubmitted || isLoading) return;
      if (!formData.message.trim()) {
        setError('Please tell us a bit about your case.');
        return;
      }

      setIsLoading(true);

      // Simulate network delay for better UX
      await new Promise(resolve => setTimeout(resolve, 1000));

      try {
        addInquiry({
          name: formData.name,
          phone: formData.phone,
          email: formData.email,
          injuryDate: formData.injury_date,
          appointmentRequestDate: formData.appointment_date,
          message: formData.message,
          howDidYouHear: formData.how_did_you_hear
        });
        setIsSubmitted(true);
      } catch (err) {
        setError('There was an error submitting your inquiry. Please try again later.');
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleBack = () => {
    setError('');
    setStep(s => s - 1);
  };

  const today = new Date().toISOString().split('T')[0];

  const renderStepContent = () => {
    if (step === 1) {
      return (
        <>
          <h2 className="text-2xl font-extrabold text-[#0F1E4A] mb-2">Step 1: Contact Information</h2>
          <p className="text-gray-600 mb-6 text-sm">We'll use this to get in touch with you about your case.</p>
          <div className="space-y-6">
            <div>
              <Label htmlFor="name" required>Full Name</Label>
              <input type="text" name="name" id="name" required value={formData.name} onChange={handleChange} className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:border-transparent transition-all" placeholder="John Doe" />
            </div>
            <div>
              <Label htmlFor="phone" required>Phone Number</Label>
              <input type="tel" name="phone" id="phone" required value={formData.phone} onChange={handleChange} className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:border-transparent transition-all" placeholder="(555) 555-5555" />
            </div>
            <div>
              <Label htmlFor="email" required>Email Address</Label>
              <input type="email" name="email" id="email" required value={formData.email} onChange={handleChange} className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:border-transparent transition-all" placeholder="john@example.com" />
            </div>
            <div className="flex justify-end pt-4">
              <button type="submit" className="w-full sm:w-auto flex justify-center items-center py-4 px-10 border border-transparent rounded-xl shadow-lg text-lg font-black text-[#0F1E4A] bg-[#FFB703] hover:bg-yellow-400 hover:scale-[1.02] transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FFB703]">
                Continue to Case Details
                <svg className="w-5 h-5 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </>
      );
    }
    if (step === 2) {
      return (
        <>
          <h2 className="text-2xl font-extrabold text-[#0F1E4A] mb-2">Step 2: Case Details</h2>
          <p className="text-gray-600 mb-6 text-sm">Tell us about your injury so we can prepare for your consultation.</p>
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <Label htmlFor="injury_date" optional>Date of Injury</Label>
                    <input type="date" name="injury_date" id="injury_date" value={formData.injury_date} onChange={handleChange} className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:border-transparent transition-all" />
                </div>
                <div>
                    <Label htmlFor="appointment_date" optional>Requested Consultation Date</Label>
                    <input 
                        type="date" 
                        name="appointment_date" 
                        id="appointment_date" 
                        min={today}
                        value={formData.appointment_date} 
                        onChange={handleChange} 
                        className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:border-transparent transition-all" 
                    />
                </div>
            </div>

            <div>
              <Label htmlFor="message" required>Tell us what happened</Label>
              <textarea id="message" name="message" rows={4} required value={formData.message} onChange={handleChange} className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:border-transparent transition-all" placeholder="Please describe the incident, your symptoms, and your current work status..."></textarea>
            </div>

            <div>
              <Label htmlFor="how_did_you_hear" optional>How did you hear about us?</Label>
              <textarea id="how_did_you_hear" name="how_did_you_hear" rows={2} value={formData.how_did_you_hear} onChange={handleChange} className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-[#FFB703] focus:border-transparent transition-all" placeholder="Google search, friend, social media, etc."></textarea>
            </div>

            <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-4">
              <button type="button" onClick={handleBack} className="w-full sm:w-auto px-8 py-4 text-sm font-bold text-gray-500 bg-gray-100 rounded-xl hover:bg-gray-200 transition-colors disabled:opacity-50" disabled={isLoading}>
                &larr; Previous Step
              </button>
              <button type="submit" className="w-full sm:w-auto flex justify-center items-center py-4 px-12 border border-transparent rounded-xl shadow-xl text-lg font-black text-[#0F1E4A] bg-[#FFB703] hover:bg-yellow-400 hover:scale-[1.02] transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FFB703] disabled:opacity-70 disabled:cursor-not-allowed" disabled={isLoading}>
                {isLoading ? (
                  <>
                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-[#0F1E4A]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Submitting...
                  </>
                ) : (
                  'Submit Inquiry'
                )}
              </button>
            </div>
          </div>
        </>
      );
    }
    return null;
  }

  return (
    <div className="bg-white">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8 pt-20 pb-32">
        <AnimatedComponent>
          <div className="text-center mb-16">
            <h1 className="text-4xl md:text-6xl font-black text-[#0F1E4A] tracking-tight">
              Start Your Journey to Recovery
            </h1>
            <p className="mt-6 max-w-2xl mx-auto text-lg md:text-xl text-gray-600 leading-relaxed font-medium">
              We offer free, confidential consultations for all California workplace injuries. Reach out today and let us fight for the benefits you deserve.
            </p>
            <div className="mt-10">
              <a href="tel:818-791-0743" className="cta-shimmer inline-flex items-center gap-3 bg-[#FFB703] text-[#0F1E4A] font-black text-xl sm:text-2xl py-4 px-10 rounded-2xl shadow-2xl hover:bg-yellow-400 transform transition-all hover:scale-105">
                <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M18.48 22.926c-4.481 0-8.956-1.708-12.383-5.135L5.135 16.829C1.708 13.403 0 8.928 0 4.447 0 2.21 1.761.447 4.025.447h1.611c1.233 0 2.308.796 2.658 1.968l1.45 4.832c.304 1.015-.1 2.115-1.002 2.716l-1.95 1.3c1.372 2.802 3.652 5.082 6.454 6.454l1.3-1.95c.601-.902 1.701-1.306 2.716-1.002l4.832 1.45c1.172.35 1.968 1.425 1.968 2.658v1.611c0 2.264-1.763 4.027-4.002 4.027z"/></svg>
                Call (818) 791-0743
              </a>
            </div>
          </div>
        </AnimatedComponent>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20 items-start">
          <div className="lg:col-span-7 bg-white p-6 sm:p-10 rounded-3xl shadow-2xl border border-gray-100 relative">
            {isSubmitted ? (
              <div className="text-center py-20 min-h-[450px] flex flex-col justify-center animate-fade-in">
                <div className="bg-green-100 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
                  <svg className="h-12 w-12 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                </div>
                <h2 className="text-4xl font-black text-[#0F1E4A] mb-4">Inquiry Sent!</h2>
                <p className="text-xl text-gray-600 font-medium">Thank you for reaching out. A member of the Jimenez Law team will review your case and contact you shortly.</p>
                <button onClick={() => setIsSubmitted(false)} className="mt-10 text-[#0F1E4A] font-bold underline hover:text-[#FFB703] transition-colors">Submit another inquiry</button>
              </div>
            ) : (
              <form onSubmit={handleFormSubmit}>
                <ProgressBar step={step} totalSteps={2} />
                <div key={step} className="animate-fade-in">
                  {renderStepContent()}
                </div>
                {error && (
                  <div className="mt-6 p-4 bg-red-50 border-l-4 border-red-500 text-red-700 flex items-center gap-3 animate-fade-in">
                    <svg className="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd"/></svg>
                    <p className="text-sm font-bold">{error}</p>
                  </div>
                )}
              </form>
            )}
          </div>

          <div className="lg:col-span-5 space-y-10">
            <AnimatedComponent style={{ transitionDelay: '200ms' }}>
              <div className="space-y-8 bg-gray-50 p-8 sm:p-10 rounded-3xl border border-gray-200 shadow-sm">
                <div>
                  <h3 className="text-xs font-black text-[#FFB703] uppercase tracking-[0.2em] mb-3">Our Office</h3>
                  <p className="text-2xl font-bold text-[#0F1E4A] mb-1">Studio City</p>
