// Caching utilities
const getCache = <T>(key: string): T | null => {
  const data = localStorage.getItem(key);
  if (!data) return null;
  const parsed = JSON.parse(data);
  return Date.now() < parsed.expires ? parsed : null;
};

const setCache = (key: string, content: any, ttl: number) => {
  localStorage.setItem(key, JSON.stringify({ ...content, expires: Date.now() + ttl }));
};

export const getWeeklyAnalysis = () => getCache<WeeklyAnalysisContent>(STORAGE_KEYS.WEEKLY_ANALYSIS);
export const setWeeklyAnalysis = (content: string) => setCache(STORAGE_KEYS.WEEKLY_ANALYSIS, { content }, 1000 * 3600 * 24 * 7);

export const getDailyNews = () => getCache<DailyNewsContent>(STORAGE_KEYS.DAILY_NEWS);
export const setDailyNews = (newsItems: NewsItem[]) => setCache(STORAGE_KEYS.DAILY_NEWS, { newsItems, lastUpdated: Date.now() }, 1000 * 3600 * 12);

export const getPracticeAreaIntroCache = () => getCache<{ content: string }>(STORAGE_KEYS.PRACTICE_INTRO)?.content || null;
export const setPracticeAreaIntroCache = (content: string) => setCache(STORAGE_KEYS.PRACTICE_INTRO, { content }, 1000 * 3600 * 24);

