import React, { useState, useEffect } from 'react';
import InquiriesDashboard from '../components/admin/InquiriesDashboard';
import BlogDashboard from '../components/admin/BlogDashboard';
import BlogPostEditor from '../components/admin/BlogPostEditor';
import AppointmentCalendar from '../components/admin/AppointmentCalendar';
import FormsDashboard from '../components/admin/FormsDashboard';
import MediaDashboard from '../components/admin/MediaDashboard';
import TeamDashboard from '../components/admin/TeamDashboard';

type AdminView = 'inquiries' | 'blog' | 'editPost' | 'calendar' | 'forms' | 'media' | 'team';

const Admin: React.FC = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [currentView, setCurrentView] = useState<AdminView>('calendar');
    const [editingPostId, setEditingPostId] = useState<number | null>(null);

    useEffect(() => {
        if (sessionStorage.getItem('jla_admin_auth') === 'true') {
            setIsAuthenticated(true);
        }
    }, []);

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        await new Promise(resolve => setTimeout(resolve, 1000));

        if (password === 'jimenezpass') {
            setIsAuthenticated(true);
            sessionStorage.setItem('jla_admin_auth', 'true');
        } else {
            setError('Incorrect password.');
        }
        setIsLoading(false);
    };

    const handleLogout = () => {
        setIsAuthenticated(false);
        setPassword('');
        sessionStorage.removeItem('jla_admin_auth');
    };

    const handleEditPost = (postId: number) => {
        setEditingPostId(postId);
        setCurrentView('editPost');
    };

    const handleAddNewPost = () => {
        setEditingPostId(null);
        setCurrentView('editPost');
    };

    if (!isAuthenticated) {
        return (
            <div className="min-h-[60vh] flex items-center justify-center bg-gray-100">
                <div className="max-w-md w-full bg-white p-8 rounded-lg shadow-md">
                    <h2 className="text-2xl font-bold text-center text-[#0F1E4A]">Admin Login</h2>
                    <form onSubmit={handleLogin} className="mt-8 space-y-6">
                        <div>
                            <label htmlFor="password-admin" className="sr-only">Password</label>
                            <input
                                id="password-admin"
                                name="password"
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                                className="appearance-none rounded-md relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703] focus:z-10 sm:text-sm"
                                placeholder="Password"
                                disabled={isLoading}
                            />
                        </div>
                        {error && <p className="text-red-500 text-xs text-center">{error}</p>}
                        <div>
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-[#0F1E4A] bg-[#FFB703] hover:bg-yellow-400 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FFB703] disabled:opacity-70 disabled:cursor-wait"
                            >
                                {isLoading ? (
                                    'Signing in...'
                                ) : (
                                    <>
                                        <span className="absolute left-0 inset-y-0 flex items-center pl-3">
                                            <svg className="h-5 w-5 text-yellow-600 group-hover:text-yellow-500" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                                                <path fillRule="evenodd" d="M10 1a4.5 4.5 0 00-4.5 4.5V9H5a2 2 0 00-2 2v6a2 2 0 002 2h10a2 2 0 002-2v-6a2 2 0 00-2-2h-.5V5.5A4.5 4.5 0 0010 1zm3 8V5.5a3 3 0 10-6 0V9h6z" clipRule="evenodd" />
                                            </svg>
                                        </span>
                                        Sign in
                                    </>
                                )}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        );
    }

    const NavButton: React.FC<{view: AdminView, label: string}> = ({view, label}) => (
        <button 
            onClick={() => setCurrentView(view)}
            className={`w-full text-left px-3 py-2 rounded-md text-sm font-medium transition-colors ${currentView === view ? 'bg-[#FFB703] text-[#0F1E4A]' : 'text-gray-700 hover:bg-gray-200'}`}
        >
            {label}
        </button>
    );

    return (
        <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-12">
            <div className="flex justify-between items-center mb-8">
                <h1 className="text-3xl font-bold text-[#0F1E4A]">Admin Dashboard</h1>
                <button onClick={handleLogout} className="text-sm font-medium text-gray-600 hover:text-[#0F1E4A]">Logout</button>
            </div>
            <div className="flex flex-col md:flex-row gap-8">
                <aside className="md:w-1/4 lg:w-1/5">
                    <nav className="space-y-2 bg-white p-4 rounded-lg shadow">
                        <NavButton view="calendar" label="Appointments" />
                        <NavButton view="forms" label="Intake Forms"/>
                        <NavButton view="media" label="Media Library" />
                        <NavButton view="team" label="Team" />
                        <NavButton view="inquiries" label="Inquiries"/>
                        <NavButton view="blog" label="Blog Posts"/>
                    </nav>
                </aside>
                <main className="flex-1 bg-white p-6 rounded-lg shadow min-h-[500px]">
                    {currentView === 'calendar' && <AppointmentCalendar />}
                    {currentView === 'inquiries' && <InquiriesDashboard />}
                    {currentView === 'forms' && <FormsDashboard />}
                    {currentView === 'media' && <MediaDashboard />}
                    {currentView === 'team' && <TeamDashboard />}
                    {currentView === 'blog' && <BlogDashboard onEditPost={handleEditPost} onAddPost={handleAddNewPost} />}
                    {currentView === 'editPost' && <BlogPostEditor postId={editingPostId} onSave={() => setCurrentView('blog')} onCancel={() => setCurrentView('blog')} />}
                </main>
            </div>
        </div>
    );
};

export default Admin;

