import React, { useState, useEffect, useRef } from 'react';
import { getAlbums, createAlbum, deleteAlbum, getMediaByAlbum, uploadMedia, deleteMedia } from '../../services/mediaService';
import type { Album, MediaItem } from '../../types';

const MediaDashboard: React.FC = () => {
    const [albums, setAlbums] = useState<Album[]>([]);
    const [selectedAlbumId, setSelectedAlbumId] = useState<string>('all');
    const [media, setMedia] = useState<MediaItem[]>([]);
    const [isCreatingAlbum, setIsCreatingAlbum] = useState(false);
    const [newAlbumName, setNewAlbumName] = useState('');
    const [isUploading, setIsUploading] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        setAlbums(getAlbums());
        setMedia(getMediaByAlbum('all'));
    }, []);

    useEffect(() => {
        setMedia(getMediaByAlbum(selectedAlbumId));
    }, [selectedAlbumId, albums]); // Refresh when album selection changes

    const handleCreateAlbum = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newAlbumName.trim()) return;
        createAlbum(newAlbumName);
        setAlbums(getAlbums());
        setNewAlbumName('');
        setIsCreatingAlbum(false);
    };

    const handleDeleteAlbum = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        if (confirm('Are you sure? This will delete all images in this album.')) {
            deleteAlbum(id);
            setAlbums(getAlbums());
            if (selectedAlbumId === id) setSelectedAlbumId('all');
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setIsUploading(true);
            const files = Array.from(e.target.files) as File[];

            // If "All" is selected, default to the first album or a "General" bucket logic (here we force user to pick an album if on 'all' usually, but for simplicity we'll put it in the first album if 'all' is selected, or just alert)
            let targetAlbumId = selectedAlbumId;
            if (targetAlbumId === 'all') {
                if (albums.length > 0) {
                    targetAlbumId = albums[0].id;
                    alert(`"All" view selected. Uploading to "${albums[0].name}" album by default.`);
                } else {
                    alert("Please create an album first.");
                    setIsUploading(false);
                    return;
                }
            }

            for (const file of files) {
                await uploadMedia(file, targetAlbumId);
            }

            setMedia(getMediaByAlbum(selectedAlbumId)); // Refresh view
            setIsUploading(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    const handleDeleteMedia = (id: string) => {
        if (confirm('Delete this image?')) {
            deleteMedia(id);
            setMedia(getMediaByAlbum(selectedAlbumId));
        }
    };

    const copyToClipboard = (url: string) => {
        navigator.clipboard.writeText(url);
        alert('Image URL copied to clipboard!');
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-200px)] min-h-[600px]">
            {/* Sidebar: Albums */}
            <div className="w-full lg:w-1/4 bg-gray-50 border border-gray-200 rounded-lg p-4 flex flex-col">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-[#0F1E4A] text-lg">Albums</h3>
                    <button 
                        onClick={() => setIsCreatingAlbum(!isCreatingAlbum)}
                        className="text-xs bg-[#FFB703] text-[#0F1E4A] font-bold px-2 py-1 rounded hover:bg-yellow-400"
                    >
                        + New
                    </button>
                </div>

                {isCreatingAlbum && (
                    <form onSubmit={handleCreateAlbum} className="mb-4">
                        <input 
                            type="text" 
                            autoFocus
                            placeholder="Album Name" 
                            className="w-full text-sm border p-1 rounded mb-2"
                            value={newAlbumName}
                            onChange={e => setNewAlbumName(e.target.value)}
                        />
                        <div className="flex justify-end gap-2">
                            <button type="button" onClick={() => setIsCreatingAlbum(false)} className="text-xs text-gray-500">Cancel</button>
                            <button type="submit" className="text-xs text-[#0F1E4A] font-bold">Create</button>
                        </div>
                    </form>
                )}

                <div className="space-y-1 overflow-y-auto flex-grow">
                    <button 
                        onClick={() => setSelectedAlbumId('all')}
                        className={`w-full text-left px-3 py-2 rounded text-sm font-medium ${selectedAlbumId === 'all' ? 'bg-white shadow text-[#0F1E4A]' : 'text-gray-600 hover:bg-gray-200'}`}
                    >
                        All Media
                    </button>
                    {albums.map(album => (
                        <div 
                            key={album.id}
                            onClick={() => setSelectedAlbumId(album.id)}
                            className={`group w-full flex justify-between items-center px-3 py-2 rounded text-sm font-medium cursor-pointer ${selectedAlbumId === album.id ? 'bg-white shadow text-[#0F1E4A]' : 'text-gray-600 hover:bg-gray-200'}`}
                        >
                            <span className="truncate">{album.name}</span>
                            <button 
                                onClick={(e) => handleDeleteAlbum(album.id, e)}
                                className="opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 font-bold px-1"
                                title="Delete Album"
                            >
                                &times;
                            </button>
                        </div>
                    ))}
                </div>
            </div>

            {/* Main Area: Gallery */}
            <div className="w-full lg:w-3/4 flex flex-col">
                <div className="flex justify-between items-center mb-6 bg-white p-4 rounded-lg border border-gray-200 shadow-sm">
                    <div>
                        <h2 className="text-2xl font-bold text-[#0F1E4A]">
                            {selectedAlbumId === 'all' ? 'All Media' : albums.find(a => a.id === selectedAlbumId)?.name || 'Album'}
                        </h2>
                        <p className="text-sm text-gray-500">{media.length} items</p>
                    </div>
                    <div>
                        <input 
                            type="file" 
                            accept="image/*" 
                            multiple 
                            ref={fileInputRef} 
                            onChange={handleFileUpload} 
                            className="hidden" 
                        />
                        <button 
                            onClick={() => fileInputRef.current?.click()} 
                            disabled={isUploading}
                            className="bg-[#0F1E4A] text-white font-bold py-2 px-6 rounded-lg hover:bg-opacity-90 transition-colors flex items-center"
                        >
                            {isUploading ? (
                                <span>Uploading...</span>
                            ) : (
                                <>
                                    <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                                    Upload Images
                                </>
                            )}
                        </button>
                    </div>
                </div>

                <div className="flex-grow bg-white border border-gray-200 rounded-lg p-4 overflow-y-auto">
                    {media.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400">
                             <svg className="w-16 h-16 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                             <p>No images in this album yet.</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                            {media.map(item => (
                                <div key={item.id} className="group relative bg-gray-100 rounded-lg overflow-hidden border border-gray-200 aspect-square">
                                    <img src={item.url} alt={item.name} className="w-full h-full object-cover" loading="lazy" />

                                    {/* Overlay */}
                                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-center items-center gap-2 p-2">
                                        <p className="text-white text-xs truncate w-full text-center px-2">{item.name}</p>
                                        <div className="flex gap-2">
                                            <button 
                                                onClick={() => copyToClipboard(item.url)}
                                                className="bg-white text-[#0F1E4A] p-2 rounded-full hover:bg-gray-200"
                                                title="Copy URL"
                                            >
                                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                                            </button>
                                            <button 
                                                onClick={() => handleDeleteMedia(item.id)}
                                                className="bg-red-500 text-white p-2 rounded-full hover:bg-red-600"
                                                title="Delete"
                                            >
                                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default MediaDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { getTeamMembers, addTeamMember, updateTeamMember, deleteTeamMember } from '../../services/contentService';
import type { TeamMember } from '../../types';

// Quill is loaded from a script tag in index.html
declare const Quill: any;

const emptyMember: Omit<TeamMember, 'id'> = {
    name: '',
    title: '',
    bio: '',
    imageUrl: ''
};

const TeamDashboard: React.FC = () => {
    const [members, setMembers] = useState<TeamMember[]>([]);
    const [isEditing, setIsEditing] = useState(false);
    const [currentMember, setCurrentMember] = useState<TeamMember | Omit<TeamMember, 'id'>>(emptyMember);

    const quillRef = useRef<HTMLDivElement>(null);
    const quillInstanceRef = useRef<any>(null);

    useEffect(() => {
        setMembers(getTeamMembers());
    }, []);

    // Initialize Quill when editing starts
    useEffect(() => {
        if (isEditing && quillRef.current && !quillInstanceRef.current) {
            const toolbarOptions = [
                ['bold', 'italic', 'underline'],
                [{ 'list': 'ordered'}, { 'list': 'bullet' }],
                ['link', 'clean']
            ];

            const quill = new Quill(quillRef.current, {
                theme: 'snow',
                modules: { toolbar: toolbarOptions },
                placeholder: 'Write the attorney bio here...'
            });
            quillInstanceRef.current = quill;

            quill.on('text-change', (delta: any, oldDelta: any, source: string) => {
                if (source === 'user') {
                    const html = quill.root.innerHTML;
                    setCurrentMember(prev => ({
                        ...prev,
                        bio: html,
                    }));
                }
            });
        }

        // Clean up when leaving edit mode
        if (!isEditing) {
            quillInstanceRef.current = null;
        }
    }, [isEditing]);

    // Sync Quill content when currentMember changes (e.g. initial load into edit mode)
    useEffect(() => {
        const quill = quillInstanceRef.current;
        if (quill && isEditing) {
            const currentQuillContent = quill.root.innerHTML;
            const bioContent = currentMember.bio || '';
            if (currentQuillContent !== bioContent) {
                quill.root.innerHTML = bioContent;
            }
        }
    }, [currentMember.bio, isEditing]);

    const handleEdit = (member: TeamMember) => {
        setCurrentMember(member);
        setIsEditing(true);
    };

    const handleAddNew = () => {
        setCurrentMember(emptyMember);
        setIsEditing(true);
    };

    const handleDelete = (id: string) => {
        if (confirm('Are you sure you want to delete this team member?')) {
            deleteTeamMember(id);
            setMembers(getTeamMembers());
        }
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        if ('id' in currentMember) {
            updateTeamMember(currentMember as TeamMember);
        } else {
            addTeamMember(currentMember);
        }
        setMembers(getTeamMembers());
        setIsEditing(false);
        setCurrentMember(emptyMember);
    };

    const handleCancel = () => {
        setIsEditing(false);
        setCurrentMember(emptyMember);
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setCurrentMember(prev => ({ ...prev, [name]: value }));
    };

    return (
        <div className="space-y-8">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold text-[#0F1E4A]">Manage Team Members</h2>
                {!isEditing && (
                    <button
                        onClick={handleAddNew}
                        className="bg-[#FFB703] text-[#0F1E4A] font-bold py-2 px-4 rounded-md hover:bg-yellow-400 transition-colors"
                    >
                        Add New Member
                    </button>
                )}
            </div>

            {isEditing ? (
                <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 shadow-sm">
                    <h3 className="text-xl font-bold text-[#0F1E4A] mb-4">
                        {'id' in currentMember ? 'Edit Team Member' : 'Add New Team Member'}
                    </h3>
                    <form onSubmit={handleSave} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700">Name</label>
                                <input
                                    type="text"
                                    name="name"
                                    value={currentMember.name}
                                    onChange={handleChange}
                                    required
                                    className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700">Title</label>
                                <input
                                    type="text"
                                    name="title"
                                    value={currentMember.title}
                                    onChange={handleChange}
                                    required
                                    className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Biography (Rich Text)</label>
                            <div className="bg-white rounded-md border border-gray-300 overflow-hidden">
                                <div ref={quillRef} className="min-h-[200px]"></div>
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700">Image URL</label>
                            <input
                                type="text"
                                name="imageUrl"
                                value={currentMember.imageUrl}
                                onChange={handleChange}
                                required
                                placeholder="https://example.com/photo.jpg"
                                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
                            />
                        </div>

                        {currentMember.imageUrl && (
                            <div className="mt-2">
                                <p className="text-sm text-gray-600 mb-1">Preview:</p>
                                <img 
                                    src={currentMember.imageUrl} 
                                    alt="Preview" 
                                    className="h-20 w-20 object-cover rounded-full border-2 border-gray-300" 
                                    onError={(e) => (e.currentTarget.style.display = 'none')}
                                    loading="lazy"
                                />
                            </div>
                        )}
                        <div className="flex justify-end gap-3 pt-4">
                            <button
                                type="button"
                                onClick={handleCancel}
                                className="bg-gray-200 text-gray-800 font-bold py-2 px-4 rounded-md hover:bg-gray-300"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                className="bg-[#0F1E4A] text-white font-bold py-2 px-4 rounded-md hover:bg-opacity-90"
                            >
                                Save Member
                            </button>
                        </div>
                    </form>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {members.map(member => (
                        <div key={member.id} className="bg-white p-4 rounded-lg shadow border border-gray-200 flex items-start space-x-4">
                            <img
                                src={member.imageUrl}
                                alt={member.name}
                                className="h-16 w-16 rounded-full object-cover border border-gray-300 flex-shrink-0"
                                loading="lazy"
                            />
                            <div className="flex-grow min-w-0">
                                <h4 className="font-bold text-[#0F1E4A] truncate">{member.name}</h4>
                                <p className="text-sm text-[#FFB703] font-semibold">{member.title}</p>
                                <div 
                                    className="text-sm text-gray-600 mt-1 line-clamp-2 prose-sm prose"
                                    dangerouslySetInnerHTML={{ __html: member.bio }}
                                />
                                <div className="mt-3 flex gap-3 text-sm">
                                    <button
                                        onClick={() => handleEdit(member)}
                                        className="text-blue-600 hover:text-blue-800 font-medium"
                                    >
                                        Edit
                                    </button>
                                    <button
                                        onClick={() => handleDelete(member.id)}
                                        className="text-red-500 hover:text-red-700 font-medium"
                                    >
                                        Delete
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

