import React, { useState, useEffect, useRef } from 'react';
import { getSettings, saveSettings } from '../../services/settingsService';
import { uploadMedia } from '../../services/mediaService';
import MediaPickerModal from './MediaPickerModal';

const SettingsDashboard: React.FC = () => {
    const [settings, setSettings] = useState(getSettings());
    const [isPickerOpen, setIsPickerOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setSettings(prev => ({ ...prev, [name]: value }));
    };

    const handleSave = () => {
        setIsSaving(true);
        saveSettings(settings);
        setTimeout(() => {
            setIsSaving(false);
            alert('Settings saved successfully! You may need to refresh the page to see changes.');
        }, 500);
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                // Upload to "Logos & Branding" album (assuming ID '1' exists from default or logic handles it)
                // We'll upload to album '1' as default for logos
                const mediaItem = await uploadMedia(e.target.files[0], '1');
                setSettings(prev => ({ ...prev, logoUrl: mediaItem.url }));
            } catch (err) {
                alert('Failed to upload image.');
            }
        }
    };

    return (
        <div className="max-w-2xl mx-auto">
            <h2 className="text-2xl font-bold text-[#0F1E4A] mb-6">Site Settings</h2>

            <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm space-y-6">

                {/* Logo Section */}
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Website Logo</label>
                    <div className="flex items-center gap-6">
                        <div className="w-24 h-24 bg-gray-100 border border-gray-300 rounded-lg flex items-center justify-center overflow-hidden">
                            <img src={settings.logoUrl} alt="Current Logo" className="max-w-full max-h-full object-contain" />
                        </div>
                        <div className="flex flex-col gap-2">
                            <input 
                                type="file" 
                                ref={fileInputRef} 
                                className="hidden" 
                                accept="image/*"
                                onChange={handleLogoUpload}
                            />
                            <div className="flex gap-2">
                                <button 
                                    onClick={() => fileInputRef.current?.click()}
                                    className="px-4 py-2 bg-[#0F1E4A] text-white text-sm font-bold rounded hover:bg-opacity-90"
                                >
                                    Upload New
                                </button>
                                <button 
                                    onClick={() => setIsPickerOpen(true)}
                                    className="px-4 py-2 bg-gray-200 text-gray-800 text-sm font-bold rounded hover:bg-gray-300"
                                >
                                    Select from Media
                                </button>
                            </div>
                            <p className="text-xs text-gray-500">Recommended size: 200x50px (PNG/SVG transparent)</p>
                        </div>
                    </div>
                </div>

                {/* General Info */}
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Firm Name</label>
                    <input 
                        type="text" 
                        name="firmName" 
                        value={settings.firmName} 
                        onChange={handleChange}
                        className="w-full border border-gray-300 rounded-md p-2 focus:ring-[#FFB703] focus:border-[#FFB703]"
                    />
                </div>

                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Main Phone Number</label>
                    <input 
                        type="text" 
                        name="phoneNumber" 
                        value={settings.phoneNumber} 
                        onChange={handleChange}
                        className="w-full border border-gray-300 rounded-md p-2 focus:ring-[#FFB703] focus:border-[#FFB703]"
                    />
                </div>

                <div className="pt-4 border-t border-gray-100">
                    <button 
                        onClick={handleSave}
                        disabled={isSaving}
                        className="w-full bg-[#FFB703] text-[#0F1E4A] font-bold py-3 rounded-md hover:bg-yellow-400 transition-colors flex justify-center items-center"
                    >
                        {isSaving ? 'Saving...' : 'Save Settings'}
                    </button>
                </div>
            </div>

            <MediaPickerModal 
                isOpen={isPickerOpen} 
                onClose={() => setIsPickerOpen(false)} 
                onSelect={(url) => setSettings(prev => ({ ...prev, logoUrl: url }))} 
            />
        </div>
    );
};

export default SettingsDashboard;

import React, { useState, useEffect } from 'react';
import InquiriesDashboard from '../components/admin/InquiriesDashboard';
import BlogDashboard from '../components/admin/BlogDashboard';
import BlogPostEditor from '../components/admin/BlogPostEditor';
import AppointmentCalendar from '../components/admin/AppointmentCalendar';
import FormsDashboard from '../components/admin/FormsDashboard';
import MediaDashboard from '../components/admin/MediaDashboard';
import TeamDashboard from '../components/admin/TeamDashboard';
import SettingsDashboard from '../components/admin/SettingsDashboard';

type AdminView = 'inquiries' | 'blog' | 'editPost' | 'calendar' | 'forms' | 'media' | 'team' | 'settings';

const Admin: React.FC = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [currentView, setCurrentView] = useState<AdminView>('calendar');
    const [editingPostId, setEditingPostId] = useState<number | null>(null);

    useEffect(() => {
        if (sessionStorage.getItem('jla_admin_auth') === 'true') {
            setIsAuthenticated(true);
        }
    }, []);

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        await new Promise(resolve => setTimeout(resolve, 1000));

        if (password === 'jimenezpass') {
            setIsAuthenticated(true);
            sessionStorage.setItem('jla_admin_auth', 'true');
        } else {
            setError('Incorrect password.');
        }
        setIsLoading(false);
    };

    const handleLogout = () => {
        setIsAuthenticated(false);
        setPassword('');
        sessionStorage.removeItem('jla_admin_auth');
    };

    const handleEditPost = (postId: number) => {
        setEditingPostId(postId);
        setCurrentView('editPost');
    };

    const handleAddNewPost = () => {
        setEditingPostId(null);
        setCurrentView('editPost');
    };

    if (!isAuthenticated) {
        return (
            <div className="min-h-[60vh] flex items-center justify-center bg-gray-100">
                <div className="max-w-md w-full bg-white p-8 rounded-lg shadow-md">
                    <h2 className="text-2xl font-bold text-center text-[#0F1E4A]">Admin Login</h2>
                    <form onSubmit={handleLogin} className="mt-8 space-y-6">
                        <div>
                            <label htmlFor="password-admin" className="sr-only">Password</label>
                            <input
                                id="password-admin"
                                name="password"
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                                className="appearance-none rounded-md relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-[#FFB703] focus:border-[#FFB703] focus:z-10 sm:text-sm"
                                placeholder="Password"
                                disabled={isLoading}
                            />
                        </div>
                        {error && <p className="text-red-500 text-xs text-center">{error}</p>}
                        <div>
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-[#0F1E4A] bg-[#FFB703] hover:bg-yellow-400 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FFB703] disabled:opacity-70 disabled:cursor-wait"
                            >
                                {isLoading ? (
                                    'Signing in...'
                                ) : (
                                    <>
                                        <span className="absolute left-0 inset-y-0 flex items-center pl-3">
                                            <svg className="h-5 w-5 text-yellow-600 group-hover:text-yellow-500" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                                                <path fillRule="evenodd" d="M10 1a4.5 4.5 0 00-4.5 4.5V9H5a2 2 0 00-2 2v6a2 2 0 002 2h10a2 2 0 002-2v-6a2 2 0 00-2-2h-.5V5.5A4.5 4.5 0 0010 1zm3 8V5.5a3 3 0 10-6 0V9h6z" clipRule="evenodd" />
                                            </svg>
                                        </span>
                                        Sign in
                                    </>
                                )}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        );
    }

    const NavButton: React.FC<{view: AdminView, label: string}> = ({view, label}) => (
        <button 
            onClick={() => setCurrentView(view)}
            className={`w-full text-left px-3 py-2 rounded-md text-sm font-medium transition-colors ${currentView === view ? 'bg-[#FFB703] text-[#0F1E4A]' : 'text-gray-700 hover:bg-gray-200'}`}
        >
            {label}
        </button>
    );

    return (
        <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-12">
            <div className="flex justify-between items-center mb-8">
                <h1 className="text-3xl font-bold text-[#0F1E4A]">Admin Dashboard</h1>
                <button onClick={handleLogout} className="text-sm font-medium text-gray-600 hover:text-[#0F1E4A]">Logout</button>
            </div>
            <div className="flex flex-col md:flex-row gap-8">
                <aside className="md:w-1/4 lg:w-1/5">
                    <nav className="space-y-2 bg-white p-4 rounded-lg shadow">
                        <NavButton view="calendar" label="Appointments" />
                        <NavButton view="forms" label="Intake Forms"/>
                        <NavButton view="media" label="Media Library" />
                        <NavButton view="team" label="Team" />
                        <NavButton view="inquiries" label="Inquiries"/>
                        <NavButton view="blog" label="Blog Posts"/>
                        <NavButton view="settings" label="Site Settings" />
                    </nav>
                </aside>
                <main className="flex-1 bg-white p-6 rounded-lg shadow min-h-[500px]">
                    {currentView === 'calendar' && <AppointmentCalendar />}
                    {currentView === 'inquiries' && <InquiriesDashboard />}
                    {currentView === 'forms' && <FormsDashboard />}
                    {currentView === 'media' && <MediaDashboard />}
                    {currentView === 'team' && <TeamDashboard />}
                    {currentView === 'blog' && <BlogDashboard onEditPost={handleEditPost} onAddPost={handleAddNewPost} />}
                    {currentView === 'editPost' && <BlogPostEditor postId={editingPostId} onSave={() => setCurrentView('blog')} onCancel={() => setCurrentView('blog')} />}
                    {currentView === 'settings' && <SettingsDashboard />}
                </main>
            </div>
        </div>
    );
};

export default Admin;

import React, { useState, useEffect, useMemo } from 'react';
import type { Page } from '../types';
import { useTranslation } from '../hooks/useTranslation';
import LanguageSwitcher from './LanguageSwitcher';
import { getSettings } from '../services/settingsService';

interface HeaderProps {
  navigate: (page: Page) => void;
  currentPage: Page;
  isMobileMenuOpen: boolean;
  setMobileMenuOpen: (isOpen: boolean) => void;
}

const Header: React.FC<HeaderProps> = ({ navigate, currentPage, isMobileMenuOpen, setMobileMenuOpen }) => {
  const { t } = useTranslation();
  const [scrolled, setScrolled] = useState(false);
  const [logoUrl, setLogoUrl] = useState('/logo.png');

  useEffect(() => {
    // Threshold set to 50px as requested for triggering visual changes
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll, { passive: true });

    // Load logo settings
    const settings = getSettings();
    if (settings.logoUrl) setLogoUrl(settings.logoUrl);

    // Listen for setting changes
    const handleSettingsChange = () => {
        const newSettings = getSettings();
        if (newSettings.logoUrl) setLogoUrl(newSettings.logoUrl);
    };
    window.addEventListener('settingsChanged', handleSettingsChange);

    return () => {
        window.removeEventListener('scroll', handleScroll);
        window.removeEventListener('settingsChanged', handleSettingsChange);
    };
  }, []);

  const navItems = useMemo(() => [
    { page: 'home', label: t('home') },
    { page: 'viability', label: t('viability_check' as any) || 'Do I Have a Case?' },
    { page: 'team', label: t('yourTeam') },
    { page: 'practice-areas', label: t('practiceAreas') },
    { page: 'case-results', label: t('caseResults') },
    { page: 'our-method', label: t('ourMethod') },
    { page: 'tools', label: t('benefitCalculator') },
    { page: 'blog', label: t('legalBlog') },
    { page: 'news', label: t('weekly_updates' as any) || 'Weekly Updates & Articles' },
    { page: 'services', label: t('services') },
    { page: 'contact', label: t('get_in_touch' as any) || 'Get in Touch' },
  ] as const, [t]);

  return (
    <>
      <header 
        className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ease-in-out ${
          scrolled 
            ? 'bg-[#0F1E4A]/95 backdrop-blur-md py-2 shadow-xl border-b border-white/5' 
            : 'bg-[#0F1E4A] py-5 border-b border-transparent'
        }`}
      >
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            {/* Branding Section */}
            <div className="flex-shrink-0">
              <button 
                onClick={() => navigate('home')} 
                className="flex items-center gap-3 transition-all hover:opacity-90 group"
                aria-label={t('firmName')}
              >
                <img 
                  src={logoUrl} 
                  alt="Jimenez Law Logo" 
                  className={`transition-all duration-500 object-contain ${scrolled ? 'h-8 sm:h-9' : 'h-10 sm:h-12'}`} 
                  loading="lazy"
                />
                <div className="flex flex-col items-start text-left">
                  <span className={`font-extrabold tracking-tight text-white transition-all duration-500 leading-none ${scrolled ? 'text-lg sm:text-xl' : 'text-xl sm:text-2xl'}`}>
                    {t('firmName')}
                  </span>
                  {!scrolled && (
                    <span className="hidden sm:block text-[10px] font-bold text-[#FFB703] uppercase tracking-[0.2em] mt-1 opacity-80 group-hover:opacity-100 transition-opacity">
                      Workers' Compensation Attorneys
                    </span>
                  )}
                </div>
              </button>
            </div>

            {/* Right Side Actions */}
            <div className="flex items-center gap-4 sm:gap-6">
                <LanguageSwitcher />

                {/* Desktop Info & CTA (Hidden on mobile) */}
                <div className="hidden lg:flex items-center gap-6">
                    <div className="flex flex-col items-end">
                        <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest leading-none mb-1">Expert Help</span>
                        <a href="tel:8187910743" className="text-white font-black text-lg hover:text-[#FFB703] transition-colors leading-none">
                        (818) 791-0743
                        </a>
                    </div>
                    <button 
                        onClick={() => navigate('contact')} 
                        className={`cta-shimmer bg-[#FFB703] text-[#0F1E4A] font-black rounded-lg transition-all transform hover:scale-105 active:scale-95 shadow-md ${scrolled ? 'py-2 px-5 text-sm' : 'py-2.5 px-6'}`}
                    >
                        {t('freeConsultation')}
                    </button>
                </div>

                {/* Unified Menu Button (Visible on ALL screens) */}
                <button 
                    onClick={() => setMobileMenuOpen(true)} 
                    className="flex items-center gap-2 p-2 sm:pr-4 sm:pl-3 rounded-lg text-gray-200 hover:text-white hover:bg-white/10 transition-colors border border-white/10 group" 
                    aria-label={t('openMainMenu')}
                >
                    <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
                    <span className="hidden sm:inline font-bold uppercase text-xs tracking-wider group-hover:text-[#FFB703] transition-colors">{t('menu')}</span>
                </button>
            </div>
          </div>
        </div>
      </header>

      {/* Backdrop for Menu Drawer */}
      <div
        className={`fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] transition-opacity duration-300 ${isMobileMenuOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setMobileMenuOpen(false)}
      />

      {/* Menu Drawer */}
      <div
        className={`fixed top-0 right-0 h-full w-full sm:w-[400px] bg-[#0F1E4A] z-[70] transform transition-transform duration-500 ease-out shadow-2xl ${isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'}`}
      >
        <div className="p-6 flex flex-col h-full">
            <div className="flex justify-between items-center mb-8 border-b border-white/10 pb-6">
                <div className="flex items-center gap-3 text-left">
                  <img src={logoUrl} alt="Logo" className="h-8 w-auto object-contain" loading="lazy" />
                  <span className="font-bold text-white text-lg">{t('firmName')}</span>
                </div>
                <button onClick={() => setMobileMenuOpen(false)} className="text-gray-300 hover:text-white p-2 border border-white/10 rounded-lg hover:bg-white/10 transition-colors">
                    <span className="sr-only">{t('closeMenu')}</span>
                    <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            </div>

            <nav className="flex-grow overflow-y-auto pr-2 custom-scrollbar">
                <ul className="space-y-2">
                    {navItems.map(item => (
                        <li key={item.page}>
                            <button
                                onClick={() => { navigate(item.page as Page); setMobileMenuOpen(false); }}
                                className={`w-full text-left px-5 py-4 rounded-xl text-lg font-bold transition-all flex items-center justify-between group ${currentPage === item.page ? 'bg-[#FFB703] text-[#0F1E4A]' : 'text-gray-200 hover:bg-white/5'}`}
                            >
                                {item.label}
                                <svg className={`w-5 h-5 transition-transform group-hover:translate-x-1 ${currentPage === item.page ? 'text-[#0F1E4A]' : 'text-gray-500 group-hover:text-[#FFB703]'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                                </svg>
                            </button>
                        </li>
                    ))}
                </ul>
            </nav>

            <div className="pt-6 border-t border-white/10 space-y-4 mt-4">
                <div className="text-center">
                    <p className="text-xs text-gray-400 uppercase tracking-widest mb-2">{t('contactUs')}</p>
