                </div>
                <button onClick={() => { navigate('contact'); setMobileMenuOpen(false); }} className="w-full bg-[#FFB703] text-[#0F1E4A] font-black py-4 rounded-xl text-xl shadow-lg hover:bg-yellow-400 transition-colors">
                    {t('freeConsultation')}
                </button>
            </div>
        </div>
      </div>
    </>
  );
};

