import React, { useState, useEffect, useRef } from 'react';
import type { BlogPost, Citation } from '../../types';
import { getBlogPostById, addBlogPost, updateBlogPost } from '../../services/contentService';
import { generateImageForPost, generateSeoSuggestions } from '../../services/geminiService';
import MediaPickerModal from './MediaPickerModal';

// Quill is loaded from a script tag in index.html and will be available on the window object
declare const Quill: any;

interface BlogPostEditorProps {
    postId: number | null;
    onSave: () => void;
    onCancel: () => void;
}

const emptyPost: Omit<BlogPost, 'id'> = {
    title: '',
    slug: '',
    excerpt: '',
    metaDescription: '',
    metaKeywords: '',
    content: '',
    imageUrl: '',
    publishedDate: new Date().toISOString().split('T')[0],
    category: 'Benefits',
    citations: [],
};

const BlogPostEditor: React.FC<BlogPostEditorProps> = ({ postId, onSave, onCancel }) => {
    const [post, setPost] = useState(emptyPost);
    const [isGenerating, setIsGenerating] = useState(false);
    const [isGeneratingSeo, setIsGeneratingSeo] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [isMediaPickerOpen, setIsMediaPickerOpen] = useState(false);

    const quillRef = useRef<HTMLDivElement>(null);
    const quillInstanceRef = useRef<any>(null);

    useEffect(() => {
        if (postId) {
            const existingPost = getBlogPostById(postId);
            if (existingPost) {
                setPost({...existingPost, citations: existingPost.citations || [] });
            }
        } else {
            setPost(emptyPost);
        }
    }, [postId]);

    useEffect(() => {
        if (quillRef.current && !quillInstanceRef.current) {
            const toolbarOptions = [
                [{ 'header': 3 }],
                ['bold', 'italic', 'underline'],
                [{ 'list': 'ordered'}, { 'list': 'bullet' }],
                ['link'],
                ['clean']
            ];

            const quill = new Quill(quillRef.current, {
                theme: 'snow',
                modules: { toolbar: toolbarOptions },
                placeholder: 'Start writing your blog post here...'
            });
            quillInstanceRef.current = quill;

            quill.on('text-change', (delta: any, oldDelta: any, source: string) => {
                if (source === 'user') {
                    const html = quill.root.innerHTML;
                    setPost(prev => ({
                        ...prev,
                        content: html,
                    }));
                }
            });
        }
    }, []);

    // Sync Quill content when post data changes
    useEffect(() => {
        const quill = quillInstanceRef.current;
        if (quill) {
            const currentQuillContent = quill.root.innerHTML;
            const postContent = post.content || '';
            // Only update if content is different to avoid cursor jumps
            if (currentQuillContent !== postContent) {
                quill.root.innerHTML = postContent;
            }
        }
    }, [post.content]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value } = e.target;

        setPost(prev => {
            const updatedPost = { ...prev, [name]: value };

            if (name === 'title') {
                updatedPost.slug = value.toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-');
            }

            return updatedPost;
        });
    };

    const handleCitationChange = (index: number, field: keyof Citation, value: string) => {
        const updatedCitations = [...(post.citations || [])];
        updatedCitations[index] = { ...updatedCitations[index], [field]: value };
        setPost(prev => ({ ...prev, citations: updatedCitations }));
    };

    const handleAddCitation = () => {
        const updatedCitations = [...(post.citations || []), { title: '', uri: '' }];
        setPost(prev => ({ ...prev, citations: updatedCitations }));
    };

    const handleDeleteCitation = (index: number) => {
        const updatedCitations = [...(post.citations || [])];
        updatedCitations.splice(index, 1);
        setPost(prev => ({ ...prev, citations: updatedCitations }));
    };

    const handleGenerateImage = async () => {
      if (!post.title) {
        alert("Please enter a title first to generate a relevant image.");
        return;
      }
      setIsGenerating(true);
      const generatedUrl = await generateImageForPost(post.title);
      if (generatedUrl) {
        setPost(prev => ({...prev, imageUrl: generatedUrl}));
      } else {
        alert("Failed to generate image. Please try again.");
      }
      setIsGenerating(false);
    };

    const handleGenerateSeo = async () => {
        if (!post.title && !post.content) {
            alert("Please provide a title and some content before generating SEO suggestions.");
            return;
        }
        setIsGeneratingSeo(true);
        try {
            const suggestions = await generateSeoSuggestions(post.title, post.content);
            if (suggestions) {
                setPost(prev => ({
                    ...prev,
                    metaDescription: suggestions.metaDescription,
                    metaKeywords: suggestions.metaKeywords,
                }));
            } else {
                alert("Failed to generate SEO suggestions. Please try again.");
            }
        } catch (error) {
            console.error("SEO generation failed:", error);
            alert("An error occurred while generating SEO suggestions.");
        } finally {
            setIsGeneratingSeo(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);

        let postToSave = { ...post };

        // Auto-generate SEO fields if they are missing
        if ((!postToSave.metaDescription || !postToSave.metaKeywords) && postToSave.title && postToSave.content) {
            try {
                // Generate in background
                const suggestions = await generateSeoSuggestions(postToSave.title, postToSave.content);
                if (suggestions) {
                    postToSave.metaDescription = postToSave.metaDescription || suggestions.metaDescription;
                    postToSave.metaKeywords = postToSave.metaKeywords || suggestions.metaKeywords;
                }
            } catch (err) {
                console.warn("Auto SEO generation failed on save:", err);
                // Continue saving even if generation fails
            }
        }

        if (postId) {
            updateBlogPost({ ...postToSave, id: postId });
        } else {
            addBlogPost(postToSave as Omit<BlogPost, 'id'>);
        }
        setIsSaving(false);
        onSave();
    };

    const metaDescLength = post.metaDescription?.length || 0;
    const descLengthColor = metaDescLength > 160 ? 'text-red-600' : (metaDescLength >= 120 ? 'text-green-600' : 'text-gray-500');

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <h2 className="text-2xl font-bold text-[#0F1E4A]">{postId ? 'Edit' : 'Add'} Blog Post</h2>

            <div>
                <label htmlFor="title" className="block text-sm font-medium text-gray-700">Title</label>
                <input type="text" name="title" id="title" value={post.title} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2" />
            </div>
            <div>
                <label htmlFor="slug" className="block text-sm font-medium text-gray-700">Slug</label>
                <input type="text" name="slug" id="slug" value={post.slug} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 bg-gray-100" />
            </div>
            <div>
                <label htmlFor="excerpt" className="block text-sm font-medium text-gray-700">Excerpt</label>
                <textarea name="excerpt" id="excerpt" rows={3} value={post.excerpt} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"></textarea>
            </div>

            <div className="space-y-4 rounded-lg border border-gray-200 p-4 bg-gray-50">
                <div className="flex justify-between items-center">
                    <h3 className="text-lg font-bold text-[#0F1E4A] flex items-center">
                        <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                        SEO Settings
                    </h3>
                    <button type="button" onClick={handleGenerateSeo} disabled={isGeneratingSeo} className="px-3 py-1 text-xs font-semibold text-[#0F1E4A] bg-[#FFB703] rounded-md hover:bg-yellow-400 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap">
                        {isGeneratingSeo ? 'Analyzing...' : '✨ Auto-Generate SEO'}
                    </button>
                </div>
                <div>
                    <label htmlFor="metaDescription" className="block text-sm font-medium text-gray-700">Meta Description</label>
                    <textarea name="metaDescription" id="metaDescription" rows={3} value={post.metaDescription} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2" placeholder="Auto-generated if left blank..."></textarea>
                    <div className="flex justify-between items-center mt-1">
                        <p className="text-xs text-gray-500">Search engine summary (120-160 chars recommended).</p>
                        <p className={`text-xs font-medium ${descLengthColor}`}>{metaDescLength} / 160</p>
                    </div>
                </div>
                <div>
                    <label htmlFor="metaKeywords" className="block text-sm font-medium text-gray-700">Meta Keywords</label>
                    <input type="text" name="metaKeywords" id="metaKeywords" value={post.metaKeywords} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2" placeholder="workers comp, injury, settlement..." />
                </div>
            </div>

            <div>
                <label htmlFor="content-editor" className="block text-sm font-medium text-gray-700">Content</label>
                <div id="content-editor" ref={quillRef} className="mt-1 bg-white min-h-[300px]"></div>
            </div>

            <div className="space-y-4 rounded-lg border border-gray-200 p-4">
                 <h3 className="text-lg font-medium text-gray-900">Post Details</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label htmlFor="imageUrl" className="block text-sm font-medium text-gray-700">Image URL</label>
                        <div className="flex gap-2">
                            <input type="text" name="imageUrl" id="imageUrl" value={post.imageUrl} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2" />
                            <button type="button" onClick={() => setIsMediaPickerOpen(true)} className="mt-1 px-3 bg-gray-200 hover:bg-gray-300 rounded-md border border-gray-300 text-sm font-bold text-gray-700 whitespace-nowrap">
                                🖼️ Library
                            </button>
                        </div>
                        <button type="button" onClick={handleGenerateImage} disabled={isGenerating} className="mt-2 px-3 py-1 text-xs font-semibold text-[#0F1E4A] bg-[#FFB703] rounded-md hover:bg-yellow-400 disabled:opacity-50 disabled:cursor-not-allowed w-full md:w-auto">
                            {isGenerating ? 'Generating...' : '✨ Generate AI Image'}
                        </button>
                    </div>
                     {post.imageUrl && (
                        <div className="mt-2">
                           <p className="block text-sm font-medium text-gray-700 mb-1">Image Preview:</p>
                           <img src={post.imageUrl} alt={post.title ? `Image preview for post: ${post.title}` : 'Blog post image preview'} className="w-full h-auto rounded-md shadow-sm max-h-40 object-cover" loading="lazy" />
                        </div>
                    )}
                    <div>
                        <label htmlFor="publishedDate" className="block text-sm font-medium text-gray-700">Published Date</label>
                        <input type="date" name="publishedDate" id="publishedDate" value={post.publishedDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2" />
                    </div>
                    <div>
                        <label htmlFor="category" className="block text-sm font-medium text-gray-700">Category</label>
                        <select 
                            name="category" 
                            id="category" 
                            value={post.category} 
                            onChange={handleChange} 
                            className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 bg-white"
                        >
                            <option value="Benefits">Benefits</option>
                            <option value="Legal Process">Legal Process</option>
                            <option value="Employee Rights">Employee Rights</option>
                            <option value="Case Studies">Case Studies</option>
                        </select>
                    </div>
                 </div>
            </div>

            <div className="space-y-4 rounded-lg border border-gray-200 p-4">
                <h3 className="text-lg font-medium text-gray-900">Citations / Sources</h3>
                <div className="space-y-3">
                {post.citations && post.citations.map((citation, index) => (
                    <div key={index} className="grid grid-cols-1 md:grid-cols-[1fr_1fr_auto] gap-4 items-center p-3 bg-gray-50 rounded-md">
                        <input 
                            type="text" 
                            placeholder="Citation Title" 
                            value={citation.title} 
                            onChange={(e) => handleCitationChange(index, 'title', e.target.value)} 
                            className="block w-full border border-gray-300 rounded-md shadow-sm p-2" 
                            aria-label="Citation Title"
                        />
                        <input 
                            type="url" 
                            placeholder="https://example.com/source" 
                            value={citation.uri} 
                            onChange={(e) => handleCitationChange(index, 'uri', e.target.value)} 
                            className="block w-full border border-gray-300 rounded-md shadow-sm p-2" 
                            aria-label="Citation URL"
                        />
                        <button 
                            type="button" 
                            onClick={() => handleDeleteCitation(index)} 
                            className="text-red-600 hover:text-red-800 font-semibold transition-colors p-2"
                            aria-label={`Delete citation ${index + 1}`}
                        >
                            Delete
                        </button>
                    </div>
                ))}
                </div>
                <button 
                    type="button" 
                    onClick={handleAddCitation} 
                    className="mt-2 px-4 py-2 text-sm font-semibold text-[#0F1E4A] bg-gray-200 rounded-md hover:bg-gray-300"
                >
                    + Add Citation
                </button>
            </div>

            <div className="flex justify-end gap-4">
                <button type="button" onClick={onCancel} className="bg-gray-200 text-gray-800 font-bold py-2 px-4 rounded-md hover:bg-gray-300" disabled={isSaving}>Cancel</button>
