                                        Delete
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            <MediaPickerModal 
                isOpen={isMediaPickerOpen} 
                onClose={() => setIsMediaPickerOpen(false)} 
                onSelect={(url) => setCurrentMember(prev => ({ ...prev, imageUrl: url }))} 
