    getPracticeAreaIntroCache, setPracticeAreaIntroCache
} from './contentService';
import { addAppointment } from './appointmentService';

const API_KEY = process.env.API_KEY;
if (!API_KEY) throw new Error("API_KEY not configured.");

const ai = new GoogleGenAI({ apiKey: API_KEY });

const MODELS = {
  PRIMARY: 'gemini-3-pro-preview',
  FLASH: 'gemini-3-flash-preview',
  IMAGE: 'gemini-2.5-flash-image'
};

const callWithRetry = async <T>(apiCall: () => Promise<T>, retries = 3, delay = 2000): Promise<T> => {
  try {
    return await apiCall();
  } catch (error: any) {
    const isRetryable = error.status === 429 || error.toString().includes('quota');
    if (isRetryable && retries > 0) {
      await new Promise(r => setTimeout(r, delay));
      return callWithRetry(apiCall, retries - 1, delay * 2);
    }
    throw error;
  }
};

const generateContent = async (contents: any, model = MODELS.PRIMARY, config: any = {}): Promise<GenerateContentResponse> => {
  try {
    return await callWithRetry(() => ai.models.generateContent({ model, contents, config }));
  } catch (error: any) {
    if (model !== MODELS.FLASH) {
      console.warn("Falling back to Flash model...");
      return await callWithRetry(() => ai.models.generateContent({ model: MODELS.FLASH, contents, config }));
    }
    throw error;
  }
};

// Optimized System Instruction for Legal Compliance & Conversion
const getSystemInstruction = () => `
**Persona:** Justice, the AI Intake Specialist for Jimenez Law, APC.
**Tone:** Empathetic, Professional, Reassuring, yet clear and direct.
**Firm Details:** Phone: (818) 791-0743. Location: Studio City, CA. Focus: Workers' Compensation.

**PRIMARY DIRECTIVES:**
1.  **NO LEGAL ADVICE:** You are NOT an attorney. Do not tell users "You have a case" or "You will win." Instead, say "This sounds like something our attorneys should review" or "Under California law, these situations often qualify for benefits."
2.  **CONVERSION IS KEY:** Your goal is to get them to (A) Schedule a free consultation, or (B) Visit the 'Viability' page.
3.  **EMPATHY FIRST:** If a user mentions pain or injury, acknowledge it first. "I'm so sorry to hear you're going through that."
4.  **GATHER INFO:** If they discuss an injury, ask *one* clarifying question at a time (e.g., "Did you report this to your employer yet?" or "Are you currently receiving medical care?").

**Tools:**
- Use 'navigateToPage' to guide them to 'viability', 'contact', or 'case-results' when relevant.
- Use 'scheduleAppointment' when they express interest in talking to a lawyer.

**Knowledge Base:**
- We work on contingency (no fee unless we win).
- We handle denied claims, specific injuries, and repetitive trauma.
- We serve all of California.
`;

const TOOLS = [
  {
    name: 'navigateToPage',
    description: "Navigates the user to a specific section of the website.",
    parameters: {
      type: Type.OBJECT,
      properties: {
        page: { type: Type.STRING, enum: ['home', 'practice-areas', 'case-results', 'tools', 'team', 'faqs', 'contact', 'blog', 'news', 'weekly-analysis', 'viability'] },
        pageName: { type: Type.STRING }
      },
      required: ['page', 'pageName'],
    },
  },
  {
    name: 'scheduleAppointment',
    description: "Schedules a consultation call.",
    parameters: {
      type: Type.OBJECT,
      properties: {
        name: { type: Type.STRING },
        date: { type: Type.STRING, description: "YYYY-MM-DD" },
        time: { type: Type.STRING, description: "HH:MM" },
        reason: { type: Type.STRING }
      },
      required: ['name', 'date', 'time', 'reason']
    }
  }
];

let activeChat: Chat | null = null;

export async function* askGeminiStream(message: string, currentPage: string): AsyncGenerator<ChatMessage> {
  if (!activeChat) {
    activeChat = ai.chats.create({
      model: MODELS.PRIMARY,
      config: {
        systemInstruction: getSystemInstruction(),
        tools: [{ functionDeclarations: TOOLS as any }],
      },
    });
  }

  try {
    const stream = await activeChat.sendMessageStream({ message: `[User is currently on page: ${currentPage}]\n\nUser Message: ${message}` });
    let fullText = '';

    for await (const chunk of stream) {
      if (chunk.text) {
        fullText += chunk.text;
        yield { sender: 'gemini', text: fullText };
      }

      if (chunk.functionCalls) {
        for (const fc of chunk.functionCalls) {
          if (fc.name === 'navigateToPage') {
            yield { sender: 'gemini', text: fullText, functionCall: { name: 'navigateToPage', args: fc.args } };
          } else if (fc.name === 'scheduleAppointment') {
            const appt = addAppointment(fc.args as any);
            const confirm = `\n\n✅ **Consultation Scheduled:** ${appt.date} at ${appt.time}. A member of our team will call you to confirm.`;
            fullText += confirm;
            yield { sender: 'gemini', text: fullText };
            await activeChat.sendMessage({ functionResponses: [{ name: 'scheduleAppointment', response: { status: 'success' }, id: fc.id }] });
          }
        }
      }
    }
  } catch (error) {
    console.error(error);
    yield { sender: 'gemini', text: "I'm having a little trouble connecting to the schedule right now. Please call our office directly at (818) 791-0743 for immediate assistance." };
  }
}

export const generateImageForPost = async (title: string): Promise<string | null> => {
  try {
    const res = await generateContent(
      `Professional, cinematic, high-contrast photorealistic image for a legal blog post titled: "${title}". Subject: Workers Compensation, Law, Justice, California. Style: Corporate, warm lighting, trustworthy. No text in image.`,
      MODELS.IMAGE,
      { imageConfig: { aspectRatio: "16:9" } }
    );
    const part = res.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : null;
  } catch { return null; }
};

