                                        <button onClick={() => onEditPost(post.id)} className="text-[#0F1E4A] hover:text-blue-700 font-semibold">Edit</button>
                                        <button onClick={() => handleDelete(post.id)} className="text-red-500 hover:text-red-700 font-semibold">Delete</button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

