const FIRM_NAME = "Jimenez Law, APC";

export const useMeta = (currentPage: Page, currentPostSlug: string | null) => {
  const { t } = useTranslation();

  useEffect(() => {
    // Map pages to their specific SEO translation keys defined in locales/*.ts
    const seoMap: Record<string, { titleKey: string, descKey: string }> = {
        'home': { titleKey: 'seo_default_title', descKey: 'seo_default_description' },
        'practice-areas': { titleKey: 'seo_practice_areas_title', descKey: 'seo_practice_areas_description' },
        'our-method': { titleKey: 'seo_our_method_title', descKey: 'seo_our_method_description' },
        'case-results': { titleKey: 'seo_case_results_title', descKey: 'seo_case_results_description' },
        'tools': { titleKey: 'seo_tools_title', descKey: 'seo_tools_description' },
        'team': { titleKey: 'seo_team_title', descKey: 'seo_team_description' },
        'faqs': { titleKey: 'seo_faqs_title', descKey: 'seo_faqs_description' },
        'contact': { titleKey: 'seo_contact_title', descKey: 'seo_contact_description' },
        'blog': { titleKey: 'seo_blog_title', descKey: 'seo_blog_description' },
        'news': { titleKey: 'seo_news_title', descKey: 'seo_news_description' },
        'weekly-analysis': { titleKey: 'seo_weekly_analysis_title', descKey: 'seo_weekly_analysis_description' },
        'terms-of-use': { titleKey: 'seo_terms_title', descKey: 'seo_terms_description' },
    };

    let title = t('seo_default_title');
    let desc = t('seo_default_description');
    let keywords = "workers compensation attorney, california work injury lawyer, jimenez law apc";

    if (currentPage === 'blogPost' && currentPostSlug) {
      // Dynamic content for blog posts
      const post = getBlogPostBySlug(currentPostSlug);
      if (post) {
        title = `${post.title} | ${FIRM_NAME}`;
        desc = post.metaDescription || post.excerpt;
        keywords = post.metaKeywords || keywords;
      }
    } else if (seoMap[currentPage]) {
      // Localized content for core pages
      title = t(seoMap[currentPage].titleKey as any);
      desc = t(seoMap[currentPage].descKey as any);
    } else if (currentPage !== 'home') {
      // Fallback for unmapped pages (e.g. services, form-viewer, admin)
      const readableName = currentPage.split('-').map(s => s.charAt(0).toUpperCase() + s.slice(1)).join(' ');
      title = `${readableName} | ${FIRM_NAME}`;
    }

    // Apply to Document Title
    document.title = title;

    // Helper to update or create meta tags
    const updateMeta = (name: string, content: string, isProperty = false) => {
      if (!content) return;
      const selector = isProperty ? `meta[property="${name}"]` : `meta[name="${name}"]`;
      let el = document.querySelector(selector);
      if (!el) {
        el = document.createElement('meta');
        if (isProperty) el.setAttribute('property', name);
        else el.setAttribute('name', name);
        document.head.appendChild(el);
      }
      el.setAttribute('content', content);
    };

    // Standard Meta
    updateMeta('description', desc);
    updateMeta('keywords', keywords);

    // Open Graph / Facebook
    updateMeta('og:title', title, true);
    updateMeta('og:description', desc, true);
    updateMeta('og:url', window.location.href, true);
    updateMeta('og:type', (currentPage === 'blogPost') ? 'article' : 'website', true);
    updateMeta('og:site_name', FIRM_NAME, true);

    // Twitter Card
    updateMeta('twitter:title', title);
    updateMeta('twitter:description', desc);

    // Canonical URL
    let canonical = document.querySelector('link[rel="canonical"]');
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    canonical.setAttribute('href', window.location.href);

  }, [currentPage, currentPostSlug, t]);
};

