import type { Album, MediaItem } from '../types';

const ALBUMS_KEY = 'jla_media_albums';
const MEDIA_KEY = 'jla_media_items';

// Initial Mock Data
const defaultAlbums: Album[] = [
    { id: '1', name: 'Logos & Branding', description: 'Official firm logos and icons', createdAt: new Date().toISOString() },
    { id: '2', name: 'Team Photos', description: 'Headshots for the Team page', createdAt: new Date().toISOString() },
    { id: '3', name: 'Case Results', description: 'Images for success stories', createdAt: new Date().toISOString() }
];

const defaultMediaItems: MediaItem[] = [
    { id: 'm1', albumId: '1', name: 'Main Logo', type: 'image/png', url: '/logo.png', uploadedAt: new Date().toISOString() },
];

// Helper to load from storage with fallback
const load = <T>(key: string, defaults: T): T => {
    try {
        const stored = localStorage.getItem(key);
        return stored ? JSON.parse(stored) : defaults;
    } catch {
        return defaults;
    }
};

const save = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

// Initialize state from storage
let albums: Album[] = load(ALBUMS_KEY, defaultAlbums);
let mediaItems: MediaItem[] = load(MEDIA_KEY, defaultMediaItems);

export const getAlbums = (): Album[] => {
    return [...albums];
};

export const createAlbum = (name: string, description?: string): Album => {
    const newAlbum: Album = {
        id: Math.random().toString(36).substring(2, 9),
        name,
        description,
        createdAt: new Date().toISOString()
    };
    albums = [...albums, newAlbum];
    save(ALBUMS_KEY, albums);
    return newAlbum;
};

export const deleteAlbum = (id: string): void => {
    albums = albums.filter(a => a.id !== id);
    // Also delete associated media to keep things clean
    mediaItems = mediaItems.filter(m => m.albumId !== id);
    save(ALBUMS_KEY, albums);
    save(MEDIA_KEY, mediaItems);
};

export const getMediaByAlbum = (albumId: string): MediaItem[] => {
    if (albumId === 'all') return [...mediaItems];
    return mediaItems.filter(m => m.albumId === albumId);
};

// Uploads a file by converting it to Base64 and saving to local storage
export const uploadMedia = async (file: File, albumId: string): Promise<MediaItem> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => {
            const newItem: MediaItem = {
                id: Math.random().toString(36).substring(2, 9),
                albumId,
                name: file.name,
                type: file.type,
                url: reader.result as string, // Store as Base64 string
                uploadedAt: new Date().toISOString()
            };
            // Add new items to the start of the list
            mediaItems = [newItem, ...mediaItems];
            save(MEDIA_KEY, mediaItems);
            resolve(newItem);
        };
        reader.onerror = error => reject(error);
    });
};

export const deleteMedia = (id: string): void => {
    mediaItems = mediaItems.filter(m => m.id !== id);
    save(MEDIA_KEY, mediaItems);
};

